/* 常识模块：法律常识（第 3/3 段） */
window.COMMON_BANK = window.COMMON_BANK || {};
window.COMMON_BANK["law"] = window.COMMON_BANK["law"] || {name:"法律常识", items:[]};
window.COMMON_BANK["law"].items.push(
{"id": "law-357", "q": "在我国，结婚的必备条件之一是：", "options": ["双方不得有血亲关系", "双方完全自愿", "双方签订婚约", "男方不得早于23 周岁，女方不得早于21 周岁"], "a": 1, "e": ".【B】《婚姻法》第5条规定，结婚必须男女双方完全自愿，不许任何一方对他方加以强迫或任何第三者加以干涉。故正确答案为B。", "tag": "法律常识"},
{"id": "law-358", "q": "公民小朱年满16 周岁，并以自己的劳动收入为主要生活来源，可以视为：", "options": ["限制民事行为能力人", "完全民事行为能力人", "无民事行为能力人", "有部分行为能力人"], "a": 1, "e": ".【B】《中华人民共和国民法总则》第十七条规定：“十八周岁以上的自然人为成年人。不满十八周岁的自然人为未成年人。”《民法总则》第十八条第二款规定：“十六周岁以上的未成年人，以自己的劳动收入为主要生活来源的，视为完全民事行为能力人。”本题中，小朱年满16周岁，并以自己的劳动收入为主要生活来源，应视为完全民事行为能力人。故正确答案为B。", "tag": "法律常识"},
{"id": "law-359", "q": "下列权利中，属于请求权的是：", "options": ["债权", "物权", "人身权", "知识产权"], "a": 0, "e": ".【A】支配权是指主体对权利客体可直接加以支配并享受其利益,同时排斥他人干涉的权利。物权、人身权、知识产权都属于支配权。请求权是指权利人请求他人为特定行为(作为、不作为)的权利。债权是典型的请求权。故正确答案为A。", "tag": "法律常识"},
{"id": "law-360", "q": "下列选项中不属于民商法调整的社会关系是：", "options": ["甲、乙两公司之间发生的买卖合同纠纷", "王某与其弟弟之间因继承发生的纠纷", "何某与其所供职的公司之间发生的知识产权纠纷", "李某与某派出所因罚款数额产生的纠纷"], "a": 3, "e": ".【D】民商法调整的是平等主体之间的财产关系和人身关系，包括民法和商法。民法主要包括物权法、债权法、人身权法、侵权法、知识产权法、婚姻家庭法、继承法等；商法（包括商主体法和商行为法）主要包括公司法、企业法、保险法、票据法、破产法、海商法、商业银行法、证券法等。A、B、C三项错误，这三项的主体地位均是平等的，涉及的都是财产关系，属于民商法调整的社会关系；D项正确，某派出所属于行政机关，李某和派出所之间的纠纷属于行政纠纷，由行政法调整。故正确答案为D。", "tag": "法律常识"},
{"id": "law-361", "q": "甲有一套商品房要出售，经人介绍，与乙签订房屋买卖合同，丙知道后找到甲，表示愿意以更高的价格购买，甲便与丙订立合同并办理房屋过户手续。下列说法正确的是：", "options": ["房屋应归乙，甲向丙承担违约责任", "房屋应归丙，甲向乙承担违约责任", "房屋产权登记有误，应重新登记为甲", "甲与丙订立的合同无效，甲与乙协商房屋的归属权"], "a": 1, "e": ".【B】文段中根据《合同法》的规定，房屋所有权的转移以是否完成房屋的过户手续为标志，文段中甲与丙订立合同办理房屋过户手续，房屋的所有权转移给丙所有，同时甲应当对乙承担合同不能履行的违约责任。故正确答案为B。", "tag": "法律常识"},
{"id": "law-362", "q": "自然人的（）始于出生，终于死亡。", "options": ["行为能力", "责任能力", "权利能力", "法律能力"], "a": 2, "e": ".【C】《中华人民共和国民法总则》第十三条规定：“自然人从出生时起到死亡时止，具有民事权利能力，依法享有民事权利，承担民事义务。”因此，ABD项不符合题意。故正确答案为C。", "tag": "法律常识"},
{"id": "law-363", "q": "甲与乙签订了一项买卖合同。约定：甲向乙支付定金5 万元，如果任何一方不履行合同应支付违约金8 万元，后来乙违约，甲打算向法院提起诉讼，下列哪种诉讼请求既能最大限度的保护自己的利益，又能获得法院的支持：", "options": ["请求乙支付违约金8 万元", "请求乙双倍返还定金10 万元", "请求乙支付违约金8 万元，同时请求返还定金5 万元", "请求乙双倍返还定金10 万元，同时请求乙支付违约金8 万元"], "a": 2, "e": ".【C】《合同法》第一百一十六条规定，当事人约定违约金，又约定定金的，一方违约时，对方可以选择适用违约金或定金条款。由此可见，二者不可并用，只能选择其中一个主张。本题可作以下分析：(1)若选择定金罚则，则乙应双倍返还定金，即10万元；(2)若选择违约金，则为约定的违约金8万元，同时由于是乙违约，所以必须返还定金5万元给甲，这样甲共获得13万元，大于定金罚则的10万元，能获得自己利益的最大化，也能得到法院支持。故C项正确；(3)禁止“并用式”选择，即甲不能要求乙支付违约金8万元，另加定金罚则的10万元，总共18万元。故D项错误。本题难点在于(2)，选择了违约金责任后，原定金收受方还要将定金原价返还，“8万+5万”之意不是违约金与定金罚则并用，而是只适用违约责任。故正确答案为C。", "tag": "法律常识"},
{"id": "law-364", "q": "甲以个人名义向乙独资设立的腾飞有限公司借款8 万元，借期2 年，不久，甲与丙登记结婚，将借款8 万元用于购买新房的家电，婚后1 年，甲与丙协议离婚，未对债务的偿还作出约定。下列哪一项是正确的：", "options": ["由乙向甲请求偿还8 万元", "由乙向甲和丙请求偿还8 万元", "腾飞公司只能向甲请求偿还8 万元", "由腾飞公司向甲和丙请求偿还8 万元"], "a": 3, "e": ".【D】本题考查法律常识，主要涉及民法的相关知识。腾飞公司虽然是个人独资企业，但其是公司法人，本题中乙须以腾飞公司的名义进行民事行为，排除A、B。《婚姻法解释(二)》第二十三条规定：“债权人就一方婚前所负个人债务向债务人的配偶主张权利的，人民法院不予支持。但债权人能够证明所负债务用于婚后家庭共同生活的除外。”本题中甲将借款8万元用于购买新房和家电，属于用于婚后家庭生活，所以应该由腾飞公司向甲和丙请求偿还债务。排除C项，D项正确。故正确答案为D。", "tag": "法律常识"},
{"id": "law-365", "q": "某制币厂为纪念奥运会特制纪念金币若干枚，每枚售价20088.8 元。其广告宣传主要内容为：（1）纪念币系纯金制造；（2）纪念币数量仅有2008 枚。后经证实，该纪念币系金铜合金，纪念币数量为20000 枚。为此，购买者与该制币厂发生纠纷。该纠纷应如何处理：", "options": ["按无效合同处理，理由为欺诈", "按可撤销合同处理，理由为欺诈", "按可撤销合同处理，理由为重大误解", "按有效合同处理"], "a": 1, "e": ".【B】《中华人民共和国民法总则》第一百四十八条规定：“一方以欺诈手段，使对方在违背真实意思的情况下实施的民事法律行为，受欺诈方有权请求人民法院或者仲裁机构予以撤销。”本题中，制币厂采用隐瞒事实和欺骗的手段销售不符合合同约定的产品，属于明显欺诈行为，购买者可按照可撤销民事法律行为的规定，主张撤销该合同。故正确答案为B。", "tag": "法律常识"},
{"id": "law-366", "q": "2009 年4 月30 日，甲以手机短信形式向乙发出购买一台笔记本电脑的要约，乙于当日回短信同意要约。但由于“五一”期间短信系统繁忙，甲于5 月3 日才收到乙的短信并因个人原因于5 月8 日才阅读乙的短信，后于9 日回复乙“短信收到”。甲乙之间买卖合同的成立时间是：", "options": ["2009 年5 月9 日", "2009 年5 月8 日", "2009 年5 月3 日", "2009 年4 月30 日"], "a": 2, "e": ".【C】本题考查法律常识，主要涉及合同的成立。《中华人民共和国合同法》第二十五条规定：“承诺生效时合同成立。”《合同法》第二十六条规定：“承诺通知到达要约人时生效。承诺不需要通知的，根据交易习惯或者要约的要求作出承诺的行为时生效。采用数据电文形式订立合同的，承诺到达的时间适用本法第十六条第二款的规定。”《合同法》第十六条第二款规定：“采用数据电文形式订立合同，收件人指定特定系统接收数据电文的，该数据电文进入该特定系统的时间，视为到达时间；未指定特定系统的，该数据电文进入收件人的任何系统的首次时间，视为到达时间。”本题中，甲于5月3日收到乙的承诺短信，此时即合同成立。故正确答案为C。", "tag": "法律常识"},
{"id": "law-367", "q": "公民能够以自己的行为取得民事权利、承担民事义务的法律资格称为：", "options": ["民事权能", "民事权利能力", "民事行为能力", "民事行为资格"], "a": 2, "e": ".【C】民事行为能力是指民事主体能以自己的行为取得民事权利、承担民事义务的资格。简言之，民事行为能力为民事主体享有民事权利、承担民事义务提供了现实性。故正确答案为C。", "tag": "法律常识"},
{"id": "law-368", "q": "著作财产权包括：", "options": ["发表权", "署名权", "修改权", "演绎权"], "a": 3, "e": ".【D】著作财产权又称“著作经济权”，是著作人身权的对称，指作者及传播者通过某种形式使用作品，从而依法获得经济报酬的权利。", "tag": "法律常识"},
{"id": "law-369", "q": "没有约定标的物的合同：", "options": ["未成立", "可以撤销", "因违法而成为无效合同", "可以解除"], "a": 0, "e": ".【A】合同成立的要件是：（1）两个或两个以上当事人；（2）双方意思表示一致（即达成一致）。《合同法》规定：当事人订立合同，采取要约、承诺方式。要约是希望和他人订立合同的意思表示，该意思表示应当符合下列规定：内容具体确定；表明经受要约人承诺，要约人即受该意思表示约束。没有标的物的意思表示内容不确定，因而合同不成立。故正确答案为A。", "tag": "法律常识"},
{"id": "law-370", "q": "下列法谚用民法规定解释错误的是（）。", "options": ["法律不保护权利上的睡眠者——超过诉讼时效期间行使权利，会丧失胜诉权", "你的权利止于我的鼻尖——民事主体不得滥用民事权利损害他人合法权益", "契约是当事人之间的法律——依法成立的合同，对当事人具有法律约束力", "借他人之手行为者，相当于自己的行为——委托他人代理某事，效果归属于代理人"], "a": 3, "e": ".【D】本题考查民法常识。A项正确，“法律不保护权利上的睡眠者”意思是法律只保护积极主张权利的人，而不保护怠于主张权利的人。依据《民法总则》第一百九十二条第一款规定：“诉讼时效期间届满的，义务人可以提出不履行义务的抗辩。”如果超过诉讼时效期间行使权利，那么胜诉权会丧失。B项正确，“你的权利止于我的鼻尖”，这句话表明民事主体行使权利是有界限的，行使自己的权利以不侵害他人的合法权益为限。依据《民法总则》第一百三十二条规定：“民事主体不得滥用民事权利损害国家利益、社会公共利益或者他人合法权益。”C项正确，“契约是当事人之间的法律”，这句话表明意思表示一致而达成的内容，双方当事人应当遵守。依据《民法总则》第一百一十九条规定：“依法成立的合同，对当事人具有法律约束力。”D项错误，“借他人之手行为者，相当于自己的行为”，这句话表明委托他人代理某事项时，代理的法律效果直接归属于本人（被代理人）。依据《民法总则》第一百六十二条规定：“代理人在代理权限内，以被代理人名义实施的民事法律行为，对被代理人发生效力。”本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-371", "q": "甲和乙是朋友，共有一所房子，份额各占一半，2017 年1 月1 日将房屋出租给了丙，租期一年，2017 年6 月甲决定将房屋卖给丁，则下列说法正确的是：", "options": ["甲卖房可以不经乙同意", "甲卖房需经丙同意", "丁购买房屋后，甲乙和丙之间的租赁合同自然失效", "丙在同等条件下，对房屋享有优先购买权"], "a": 3, "e": ".【D】本题考查法律常识。A项错误，根据《中华人民共和国物权法》第九十七条规定：“处分共有的不动产或者动产以及对共有的不动产或者动产作重大修缮的，应当经占份额三分之二以上的按份共有人或者全体共同共有人同意，但共有人之间另有约定的除外。”所以甲卖房屋需要经过乙同意。B项错误，根据《中华人民共和国合同法》第二百三十条规定：“出租人出卖租赁房屋的，应当在出卖之前的合理期限内通知承租人，承租人享有以同等条件优先购买的权利。”所以房屋卖出之前应该通知丙，而非征求丙的同意。C项错误，根据《中华人民共和国合同法》第二百二十九条规定：“租赁物在租赁期间发生所有权变动的，不影响租赁合同的效力。”这就是所谓的“买卖不破租赁”，因此，该租赁合同依然有效。D项正确，根据《中华人民共和国合同法》第二百三十条规定：“承租人享有以同等条件优先购买的权利。”丙是承租人，所以享有优先购买权。故正确答案为D。", "tag": "法律常识"},
{"id": "law-372", "q": "下列哪一情形不构成代理权的滥用（）", "options": ["甲受乙的委托，出售乙的二手汽车，甲自己买下，而此事乙不知情", "甲受乙委托购买手机，结果甲以乙的名义购买了一批平板电脑", "甲受乙委托买房，受丙的委托卖房，于是甲将丙的房子直接卖给了乙，而此事乙丙均不知情", "甲受乙委托购买机器，甲与机器销售商丙约定以高价成交，多余的钱二人平分"], "a": 1, "e": ".【B】本题考查法律常识。代理权的滥用，是指代理人违反“以被代理人利益为出发点”的代理原则所实施的代理行为。代理权的滥用包括四种情形：（1）双方代理，（2）自己代理，（3）利己代理，（4）恶意串通的代理。其中，双方代理是指代理人同时受交易双方委托，为双方的交易实施代理；自己代理是指代理人以被代理人的名义同自己进行民事行为；利己代理是指代理人利用地位之便，实施利于自己却不利于被代理人的代理；恶意串通的代理是指代理人与相对人恶意串通，损害被代理人利益的代理。A项正确，《中华人民共和国民法总则》第一百六十八条第一款规定：“代理人不得以被代理人的名义与自己实施民事法律行为，但是被代理人同意或者追认的除外。”即禁止自己代理。因此，甲以乙的名义与自己实施代理行为，构成自己代理，属于代理权的滥用。B项错误，甲有购买手机的代理权限，但没有购买平板电脑的代理权限，故构成无权代理。在无权代理的情况下，不存在代理权的滥用。C项正确，《中华人民共和国民法总则》第一百六十八条第二款规定：“代理人不得以被代理人的名义与自己同时代理的其他人实施民事法律行为，但是被代理的双方同意或者追认的除外。”即禁止双方代理。因此，构成双方代理，属于代理权的滥用。D项正确，《中华人民共和国民法总则》第一百六十四条第二款规定：“代理人和相对人恶意串通，损害被代理人合法权益的，代理人和相对人应当承担连带责任。”即禁止恶意串通的代理。因此，甲与丙高价成交，多余的钱平分的约定，构成恶意串通的代理，属于代理权的滥用。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-373", "q": "下列对法谚的解读正确的是：", "options": ["法无授权不可为——每个公民都应当严格按照法律的规定作为", "枪炮作响法无声——战乱时，平常法律所维系的社会秩序荡然无存", "法律必须被信仰，否则它将形同虚设——法律规定与道德信仰相辅相成，互相促进", "法不阿贵，绳不挠曲——即使初衷是好的，如果触犯了法律还是要一视同仁"], "a": 1, "e": ".【B】本题考查法理学有关知识。A项错误，“法无授权不可为”指国家公权力的行使必须经过法律授权，强调政府必须谨慎运用手中的每一份权力，而不是每个公民应当按照法律的规定作为。B项正确，“枪炮作响法无声”来源于古罗马，指的是当发生战乱的时候，平常法律所维系的社会秩序便会荡然无存，冲突的解决完全凭借暴力。C项错误，“法律必须被信仰，否则它将形同虚设”出自伯尔曼的《法律与宗教》。它指的是，一个人只有从内心深处真正认同、信任和信仰法律，才会自觉维护法律的权威。未体现道德信仰与法律的关系。D项错误，“法不阿贵，绳不挠曲”是韩非子的话，意为法律不迎合权贵，就像木匠用的墨线决不会屈就于弯曲的木料一样，说明法律面前人人平等，不因对象是贵族而改变，没有提到初衷。故正确答案为B。", "tag": "法律常识"},
{"id": "law-374", "q": "下列做法最贴近“看得见的正义才是真正的正义”法律内涵要求的是：", "options": ["纪检监察部门开通网站并接受网络举报", "地方政府在互联网上征求城市规划意见", "人民法院在互联网上公布法庭裁判文书", "交警配备执法记录仪实时记录执法过程"], "a": 2, "e": ".【C】“看得见的正义才是真正的正义”意思是说：“正义不仅要实现，而且要以看得见的方式实现。”干提到的法律内涵，排除。B项错误，明显与题干无关，征求城市规划意见是民主的体现，不能体现“看得见的正义才是真正的正义”的法律内涵，排除。C项正确，党的十八届三中全会提出了要完善“司法公开制度”，“让人民监督权力，让权力在阳光下运行”。裁判文书的公示对司法公正无疑有一种保证和促进作用。正所谓“正义不仅要实现而且需以看得见的方式实现”，裁判文书是对当事人争议焦点、辩论观点的归纳，是对法院裁判观点形成的逻辑阐释，是司法过程的最终载体。故裁判文书公示不仅使当事人赢得堂堂正正、输得明明白白，也将法院的司法过程、司法结果置于社会所有公众的监督、审视之下，接受公众的评判，当选。D项错误，此项是行政机关对执法人员的执法过程的监督，不能体现题干提到的法律内涵，排除。故正确答案为C。", "tag": "法律常识"},
{"id": "law-375", "q": "对下列古语所蕴含法律思想的理解，不正确的是", "options": ["法不察民情而立之，则不威——法律应当服从民意", "刑罚不足以移风，杀戮不足以禁奸——严刑峻法有其局限性", "国有常法，虽危不亡——法律是国家长治久安的保障", "天下之事，不难于立法，而难于法之必行——法律的生命力在于实施"], "a": 0, "e": ".【A】本题考查法律常识。A项错误，出自《商君书•壹言》，意思是如果不体察民情民意就制定法律，那么法律会失去权威。这句古语说明法律的最终目的是服务于民众，制定法律必须考虑民意，但并不意味着法律应当服从民意，这是因为法律的本质是统治阶级进行阶级统治的工具。正如卢梭所说：“明智的创造者并不从制定良好的法律本身着手，而是要事先考察一下，他要为之而立法的那些人民是否适于接受那些法律。”B项正确，出自《淮南子•主术训》，意思是单靠刑罚不能够改变社会的不良风气，单靠杀戮也不能够禁止坏人坏事。这句古语说明严刑峻法也有其局限性，要想社会秩序井然，不能仅靠刑罚，还要靠道德教育。C项正确，出自《韩非子•饰邪》，意思是国家有稳定的法度，虽遇到危难也不致灭亡。这句古语说明法律是国家长治久安的保障。D项正确，出自明代张居正的《请稽查章奏随事考成以修实政疏》，意思是天下的事情，困难之处不在于制定法令，而在于让法令得到切实贯彻执行。这句古语说明法律的生命力在于实施。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-376", "q": "司法公正体现在司法活动各个方面和对司法人员的要求上。下列（）做法体现的不是司法公正的内涵。", "options": ["甲法院对社会关注的重大案件通过微博直播庭审过程", "乙法院将本院公开审理后作出的判决书在网上公布", "丙检察院为辩护人查阅、摘抄、复制案卷材料提供便利", "丁检察院为暴力犯罪的被害人提供医疗和物质救助"], "a": 3, "e": ".【D】本题考查法律常识。根据司法的理论与实践，司法公正主要体现在以下几方面：（1）司法活动的合法性。合法性是指司法机关审理案件要严格按照法律的规定办事。不仅要按实体法办事，而且要按程序法办事。（2）司法人员的中立性，如法官的中立性。（3）司法活动的公开性。诉讼程序的每一阶段和步骤都应当以当事人和社会公众看得见的方式进行。例如，法院应当努力实现立案公开、庭审公开、审判结果公开、裁判文书公开和执行过程公正。（4）当事人地位的平等性。一是当事人享有平等的诉讼权利，二是法院平等地保护当事人诉讼权利的行使。（5）司法程序的参与性。程序参与性又称为“获得法庭审判机会”，指那些利益或权利可能会受到民事裁判或诉讼结局直接影响的人应当有充分的机会富有意义地参与诉讼的过程，并对裁判结果的形成发挥其有效的影响和作用。（6）司法结果的正确性。适用法律时，事实要调查清楚；证据要确凿可靠，经得起历史检验；对案件的定性要准确；处理要适当。A项、B项正确，属于司法活动的公开性，体现了司法公正。C项正确，这是司法程序的参与性体现，属于司法公正。D项错误，该检察院的刑事被害人救助有关工作与司法公正无关。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-377", "q": "《宪法》第五十一条规定：“中华人民共和国公民在行使自由和权利的时候，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。”关于该条文，下列说法正确的是（）。", "options": ["表达的是授权性规则", "表达的是禁止性规则", "表达的是程序性原则", "表达了法律规则中的法律后果"], "a": 1, "e": ".【B】本题考查法律常识。A项错误，授权性规则是指示人们可以作为、不作为或要求别人作为、不作为的规则。授权性规则的特点是为权利主体提供一定的选择自由，对于权利主体来说不具有强制性，它既不强令权利人作为，也不强令权利人不作为。相反，它为行为人的作为、不作为提供了一个自由选择的空间。B项正确，禁止性规范通常称为禁止性规定，是“命令当事人不得为一定行为之法律规定”，属于“禁止当事人采用特定模式的强行性规范”。本题中，《宪法》明确规定公民在行使自由和权利的时候，不得损害其他主体的自由和权利，属于禁止性规定。C项错误，程序性法律原则是规定程序性法律问题的原则。程序性法律原则的功能是调整程序上的权利义务关系，例如，公开原则、回避原则、司法独立原则、谁主张谁举证原则、排除非法证据原则等。D项错误，法律后果，指法律规则中规定人们在作出符合或不符合行为模式的要求时应承担相应的结果的部分，是法律规则对人们具有法律意义的行为的态度。该条文没有规定法律后果。故正确答案为B。", "tag": "法律常识"},
{"id": "law-378", "q": "下列法律法规中，哪一项不是从2019 年1 月1 日起施行？", "options": ["《中华人民共和国电子商务法》", "《中华人民共和国土壤污染防治法》", "新修订的《中华人民共和国公务员法》", "新修订的《中华人民共和国个人所得税法实施条例》"], "a": 2, "e": ".【C】本题考查法律。A项正确，《中华人民共和国电子商务法》是2018年8月31日第十三届全国人民代表大会常务委员会第五次会议通过，本法第八十九条规定：“本法自2019年1月1日起施行。”B项正确，《土壤污染防治法》是2018年8月31日十三届全国人大常委会第五次会议全票通过，本法第九十九条规定：“本法自2019年1月1日起施行。”C项错误，《中华人民共和国公务员法》已由中华人民共和国第十三届全国人民代表大会常务委员会第七次会议于2018年12月29日修订通过，自2019年6月1日起施行。D项正确，《中华人民共和国个人所得税法实施条例》是国务院发布的法规，2018年12月18日中华人民共和国国务院令第707号第四次修订通过，第三十六条规定：“本条例自2019年1月1日起施行。”本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-379", "q": "下列说法与其所蕴涵的法治原则对应不正确的是：", "options": ["切蛋糕者最后拿蛋糕——效率原则", "两害相权取其轻——利益权衡原则", "有恒产者有恒心——人权保障原则", "法无授权不可为——权力制约原则"], "a": 0, "e": ".【A】本题考查法治原则相关知识。蛋糕。体现的是公平原则，而不是效率原则。B项正确，两害相较取其轻，指把两项祸事进行比较，选取其中较轻的一项，体现的是利益权衡原则。C项正确，这句话出自孟子的《孟子滕文公上》，孟子主张人民应有“恒产”，即土地，孟子不拥护土地私有，而是维护农民稳定占有、使用土地的权利，体现的是人权保障原则，也就是保障人的生存和发展。D项正确，所谓的法无授权不可为，指国家公权力的行使必须经过法律授权，体现了权力制约原则。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-380", "q": "法律调整是一种：", "options": ["个别性调整", "规范性调整", "习惯性调整", "具体性调整"], "a": 1, "e": ".【B】本题考查法理学相关内容。法律调整是国家根据自己的价值评断，以法的形式对人的行为进行规范，对现实社会生活关系施加影响，以期建立理想的社会生活秩序的活动。它有两个特点：(1)法律调整是与国家和法同时产生的，是统治阶级运用国家权力对社会关系所作是带有价值判断的规范性和组织性的中介；(2)法律调整具有有目的、有组织、有结果的性质，并有国家强制力作为后盾。由此可以看出，法律调整是一种规范性调整。故正确选项为B。", "tag": "法律常识"},
{"id": "law-381", "q": "诉讼程序的启动总是以具体案件的发生为前提，不论是刑事诉讼、民事诉讼还是行政诉讼，都通常必须由诉讼参与人的诉讼行为来启动，这说明诉讼活动具有。", "options": ["主动性", "被动性", "独立性", "权威性"], "a": 1, "e": ".【B】本题考查法律常识，主要涉及法律适用特点等相关知识点。A项错误，主动性是执法的特征，被动性是司法的特征。主动性要求执法机关应当积极主动地去执行法律，而不一定需要行政相对人的请求和同意。因此诉讼活动并不具备主动性，故A项错误。B项正确，司法过程的启动总是以具体案件的发生为前提，在大多数案件中，司法活动必须由当事人的诉讼行为来启动。这种消极性和被动性是由法院作为中立的第三者的地位所决定的，裁判者只能是中立的第三者。这种消极性和被动性在诉讼上主要体现为，诉讼的启动权在当事人，当事人没有行使诉讼权，提起诉讼时，法院不能主动开始诉讼程序；当事人没有提出的请求和主张，法院不能主动进行审查和判断。故B项正确。C项错误，独立性体现在人民法院依法独立行使审判权，人民检察院依法独立行使检察权，不受行政机关、社会团体和公民个人的非法干涉。与题干无关，故C项错误。D项错误，权威性体现在国家机关尤其是司法机关的活动是以国家名义进行的，司法裁决一旦发生法律效力，任何组织和个人都必须执行，不得擅自修改和违抗。与题干无关，故D项错误。故正确答案为B。", "tag": "法律常识"},
{"id": "law-382", "q": "下列谚语与法律用语不相对应的是：", "options": ["每一个人都不可能成为自己事务的法官——回避", "法律只帮助警醒的人，而不帮助惫懒的人——诉讼时效", "存疑不能认定，疑点利益归于被告——罪刑法定", "如为他人制定法律，应将同一法律应用于自身——法律面前人人平等"], "a": 2, "e": ".【C】A项正确，这句话的意思是任何人作为争议案件的当事人不可以自己充当法官来裁决案件的是非对错，因为人都有偏袒自己的心理。扩大一点，人通常也会偏袒自己的亲朋故旧。因此，在一个人成为争议案件的当事人或者与当事人有密切关系、或者与案件有利害关系时，不可以充当案件的裁断者。在现代法律中，解决争议的相关法律制度中都贯彻了这一原则，主要表现为回避制度。B项正确，诉讼时效是指民事权利受到侵害的权利人在法定的时效期间内不行使权利，当时效期间届满时，债务人获得诉讼时效抗辩权。在法律规定的诉讼时效期间内，权利人提出请求的，人民法院就强制义务人履行所承担的义务。而在法定的诉讼时效期间届满之后，权利人行使请求权的，人民法院就不再予以保护。所以在诉讼时效问题上，无论对原告还是被告，都要及时行使权力。C项错误，疑点利益归于被告原则，又称为存疑时有利于被告原则，是指在刑事诉讼中遇到事实无法查清或查清事实所需成本过高的情况，依有利于被告的原则判决，该原则是刑法通过限制国家的刑罚权从而保障行为人自由机能的体现。这一原则也可用于诉讼前提条件，如无法确信某犯罪行为是否超过追诉时效时，应当认为已经超过追诉时效而不再追诉。D项正确，这句话出自阿奎那，指的是在制定法律时也要把自己考虑进去，在现代法律中指的是法律面前人人平等。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-383", "q": "“周瑜打黄盖，一个愿打一个愿挨。”这句俗语所蕴含的法律含义是：", "options": ["原告自认", "受害人同意", "过错相抵", "契约自由"], "a": 1, "e": ".【B】本题考查法理学的有关知识。A项错误：原告自认是指当事人一方承认对方当事人所主张的不利于自己的事实主张，这可以作为真实明确地表明其真实性的陈述。题干中“周瑜打黄盖”并未体现原告自认原则。B项正确：受害人同意原则是侵权行为法的一项重要法律原则。从语义上讲，是指某人对某一事实或者行为作出的允许或者承认。在侵权法上，受害人同意就是受害人对其受害作出的允许或者承认。从“周瑜打黄盖”的案例进行分析，侵害人周瑜造成了实质上的违法行为，但由于黄盖对周瑜的侵害行为表示认可，根据受害人同意原则，在侵权法上侵害人周瑜可以获得免责。C项错误：过错相抵是指在加害人依法应承担损害赔偿责任的前提下，如果受害人对于损害事实的发生或扩大也有过错，则可以减轻加害人的赔偿责任。题干中“周瑜打黄盖”并未体现过错相抵原则。D项错误：契约自由是指个人之间的契约关系，应根据契约当事人的自由意思决定，而不得受到其他任何个人和组织的干涉。题干中“周瑜打黄盖”并未体现契约自由原则。故正确答案为B。", "tag": "法律常识"},
{"id": "law-384", "q": "下列4 个日常生活谚语与我国现行法律法规不完全一致的是：①法不责众②父债子还③欠债还钱④杀人偿命", "options": ["①②③", "①②④", "②③④", "①②③④"], "a": 3, "e": ".【D】①法不责众，与我国现行法律规定不一致。法具有“规范性、强制性、普遍性”，宪法规定“我国公民在法律面前一律平等”，法治有“违法必究”原则，刑法有“罪责刑相适应”原则，故“法应责众”，对于违法分子，并不考虑人数多寡，均应受到法律惩处。②父债子还，与我国现行法律规定不完全一致。根据《继承法》第三十三条规定：“继承遗产应当清偿被继承人应当缴纳的税款和债务，缴纳税款和清偿债务应以他的遗产实际价值为限。”故父债，如果子女继承其父母遗产的才需要代偿，如不继承无需代偿。③欠债还钱，与我国现行法律规定不完全一致。民法规定债务除清偿外，还有免除、混同、抵销、提存4种方式，其中混同（债权人、债务人归于同一人的事实）、免除（债权人放弃债权）均无需履行债务，即欠债无需还钱。④杀人偿命，与我国现行法律规定不完全一致。根据《刑法》第二百三十二条规定：“【故意杀人罪】故意杀人的，处死刑、无期徒刑或者十年以上有期徒刑；情节较轻的，处三年以上十年以下有期徒刑。”可知，杀人存在无需“偿命”的情况。①②③④都与现行法律规定不完全一致。故正确答案为D。", "tag": "法律常识"},
{"id": "law-385", "q": "大学生李某的一项发明获省级科技竞赛一等奖，为防止该项发明被他人非法利用，李某依法申请了专利。李某的做法所体现的法的作用是：", "options": ["指引作用", "评价作用", "教育作用", "强制作用"], "a": 0, "e": ".【A】本题考查法理学的有关知识。A项正确：指引作用是指法（主要是法律规范）对本人行为起到导向、引路的作用。指引作用的对象是每个人自己的行为。李某自己申请专利的行为体现了法的指引作用。B项错误：评价作用是指法作为一种社会规范，具有判断、衡量他人行为是否合法或有效的作用。题干中未体现评价作用。C项错误：教育作用是指通过法的实施，法律规范对人们今后的行为发生直接或间接的诱导影响。题干中未体现教育作用。D项错误：强制作用是指法对违法犯罪者的行为具有制裁、惩罚作用。法的强制作用是法的其他作用的保证。题干中未体现强制作用。故正确答案为A。", "tag": "法律常识"},
{"id": "law-386", "q": "下列对司法俗语说明错误的是：", "options": ["案结事了——司法解决的根本性", "有告必理——司法解决的普遍性", "不告不理——司法活动的被动性", "一事不再理——司法程序的终结性"], "a": 1, "e": ".【B】A项说法正确：“案结事了”是指审结案件之后能真正地化解纠纷和矛盾，体现了司法解决的根本性。B项说法错误：“有告必理”是指法院不再对诉讼要件进行实质审查，一律接收诉状，法院“有案不立”将被追责，任何单位、个人不得干预法院立案，体现的是司法解决的公平正义而非普遍性。C项说法正确：“不告不理”是指如果没有原告的起诉，法院就不能进行审判，体现了司法活动的被动性。D项说法正确：“一事不再理”体现了司法程序的终结性。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-387", "q": "按照相关规定，我国驻外大使由（）根据全国人民代表大会常务委员会的决定任免。", "options": ["国家主席", "国务院总理", "全国人大常委会委员长", "外交部部长"], "a": 0, "e": ".【A】根据《中华人民共和国宪法》第八十一条规定：“中华人民共和国主席……根据全国人民代表大会常务委员会的决定，派遣和召回驻外全权代表，批准和废除同外国缔结的条约和重要协定。”国家主席具有任免权，所以由国家主席任免驻外大使。故正确答案为A。", "tag": "法律常识"},
{"id": "law-388", "q": "因张三不偿还一年前的十万元现金借款(利率5%)，李四将其诉至法院，但李四丢失了借条原件，面临败诉的风险，最后在法院的调解下，张三自愿偿还李四现金十万元，李四主动放弃利息的诉讼请求，下列法谚内涵最能体现这一调解精神的是：", "options": ["无救济，即无权利", "法者，定纷止争也", "善良的心，是最好的法律", "举证之所在，败诉之所在"], "a": 2, "e": ".【C】英国法学家麦克莱有句至理名言，“善良的心是最好的法律”。张三从拒不偿还到自愿偿还李四现金十万元，李四主动放弃利息的诉讼请求，这都体现了人性的善，在调解下解决了纷争，体现了“善良的心是最好的法律”这一调解精神。A、B、D三项都不是调解精神，是法的精神和举证责任原则。故正确答案为C。", "tag": "法律常识"},
{"id": "law-389", "q": "下列法律谚语与其蕴含的法学理论对应正确的是：", "options": ["法无明文授权不得为：人的权利根源于法条", "在法律面前人人平等：人的自由不能被剥夺", "迟到的正义不是正义：效率是法的价值目标", "民若不告则官必不究：诉权只能由个人行使"], "a": 2, "e": ".【C】A项错误，人的权利根源于人的自然属性和社会属性，而“法无明文授权不得为”是指权力部门的行为应当严格按照法律的规定作为；B项错误，“法律面前人人平等”是指在法律面前每个人的地位是一样的，与自由是否被剥夺无关，而人在触犯法律的情况下是可以被剥夺自由的，如有期徒刑、死刑等刑罚；C项正确，迟到的正义说明在事件发生的当下，法律没有达到应有的维护正义的作用，导致了事件发生当时的不正义，所以强调效率的重要性；D项错误，“民不告则官不究”主要是针对民事诉讼和刑事诉讼中的自诉案件，诉权也可由检察院行使。故正确答案为C。", "tag": "法律常识"},
{"id": "law-390", "q": "《人民日报》评论指出：“一个人挥舞胳膊的自由止于别人鼻子的地方。”下列可以代替该评论的名言是：", "options": ["哪里没有法律，哪里就没有自由", "法典就是人民自由的圣经", "法律是自由的保姆", "自由只服从法律"], "a": 0, "e": ".【A】此题为争议题。A项洛克曾说：“哪里没有法律，哪里就没有自由。”强调公民要依法行使权利和自由，和题目中一个人虽然可以随意挥舞自己的胳膊，但是也不能超过一定的界限相吻合。故表述正确。B项马克思说“法典就是人民自由的圣经。”说的意思是法律要保障人民的利益和自由，但题目的侧重点不在保障自由上，故不合题意。C项柏拉图说：“法律是自由的保姆。”跟B项类似，侧重点在保障自由上，跟题意不符。D项伏尔泰说：“自由只服从法律。”确实自由的行使权利也是有边界的，但是“只”字题目没有体现出来，相比之下A项更合适。故粉笔题库倾向答案为A。故正确答案为A。", "tag": "法律常识"},
{"id": "law-391", "q": "下列说法中正确的是：", "options": ["正当防卫必须是针对实施不法侵害的行为人进行的防卫", "法制优于法治", "正当防卫必须是口头警告后实施的行为", "法治等同于法制"], "a": 0, "e": ".【A】B项、D项错误。法治是法律统治的简称，内涵是一种治国理论、原则和方法，法治是相对于“人治”而言的；而法制是法律制度的简称，内涵是指法律及相关制度，属于制度的范畴。法治是法制的立足点和归宿，法制的发展前途必然是最终实现法治；法制是法治的基础和前提条件，要实行法治，必须具有完备的法制制度，法治的实施必须建立在法制之上。故B项“法制优于法治”、D项“法治等同于法制”的表述都是错误的。根据我国《刑法》第二十条规定：为使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，对不法侵害人造成损害的，属于正当防卫，不负刑事责任。故A项“正当防卫必须是针对实施不法侵害的行为人进行的防卫”表述正确。而C项“正当防卫必须是口头警告后实施的行为”并没有法律依据，错误。故正确答案为A。", "tag": "法律常识"},
{"id": "law-392", "q": "维护社会公平正义的最后一道防线是（）。", "options": ["立法", "执法", "司法", "道德"], "a": 2, "e": ".【C】习近平主席2014年7月在中央政法工作会议上指出：促进社会公平正义是政法工作的核心价值追求。从一定意案。由上述讲话内容可知，C项表述正确，此外从立法、执法和司法三者产生和发生效力的时间阶段来说C项也是排在最后的。故正确答案为C。", "tag": "法律常识"},
{"id": "law-393", "q": "2013 年4 月，吴某在微博上散布H7N9 禽流感在宁波某地暴发的谣言。当地警方依法对其作出拘留五日的处罚。吴某的行为属于：", "options": ["违纪行为", "行政违法行为", "民事违法行为", "犯罪行为"], "a": 1, "e": ".【B】《中华人民共和国治安管理处罚法》第二十五条规定：有下列行为之一的，处5日以上10日以下拘留，可以并处500元以下罚款；情节较轻的，处5日以下拘留或者500元以下罚款：（一）散布谣言，谎报险情、疫情、警情或者以其他方法故意扰乱公共秩序的；（二）投放虚假的爆炸性、毒害性、放射性、腐蚀性物质或者传染病病原体等危险物质扰乱公共秩序的。吴某的行为属于行政违法行为。故正确答案为B。", "tag": "法律常识"},
{"id": "law-394", "q": "下列活动中，属于司法活动范畴的是：", "options": ["某司法局审查并发放律师执业证", "陕西省高级人民法院向陕西省人民代表大会做工作报告", "交警对王某的交通违章进行罚款处罚", "检察机关对犯罪嫌疑人柳某的涉嫌受贿犯罪予以批准逮捕"], "a": 3, "e": ".【D】司法，又称法的适用，通常是指国家司法机关及其司法人员依照法定职权和法定程序，具体运用法律处理案件的专门活动。A、B项均不涉及处理案件，排除；C项中交警不是刑法意义上的司法人员，且涉及行为只是单纯的行政处罚行为，排除；D项符合司法所涉及的内容，当选。故正确答案为D。", "tag": "法律常识"},
{"id": "law-395", "q": "下列有关社会主义法律与社会主义道德的表述，不正确的是：", "options": ["二者都是社会主义经济基础的产物", "二者都是由国家强制力保证实施的", "二者都是调整人们相互关系的行为规范"], "a": 1, "e": ".【B】本题考查社会主义法律与社会主义道德的关系。社会主义法律与社会主义道德在本质上是一致的，它们都是社会的。但两者又有区别，社会主义法律是社会主义国家制定和认可的规范性文件，由国家强制力保障实施，而社会主义道德是由社会舆论确立的一般社会意志，由人们内心信念和社会舆论来保证其存在和发生作用。A、C、D表述正确；B项说二者都由国家强制力保证实施的，错误。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-396", "q": "按法律关系所体现的社会内容的性质，可将其分为：", "options": ["绝对法律关系和相对法律关系", "平权型法律关系和隶属型法律关系", "基本法律关系、普通法律关系和诉讼法律关系", "成文法律关系和习惯法律关系"], "a": 2, "e": ".【C】A项错误，是依据义务人的范围不同进行的分类；B项错误，是按照法律关系各主体之间的法律地位是否平等进行的分类；C项正确，按法律关系所体现的社会内容的性质，法律关系分为基本法律关系、普通法律关系和诉讼法律关系；D项错误，是按照法律制定程序不同进行的分类。故正确答案为C。", "tag": "法律常识"},
{"id": "law-397", "q": "某保安公司与湖南省邵东县综合治理委员会办公室签订协议，以每月7.5 万元的承包费，在夜里10 点到次日早6 点，为县城区提供有偿治安巡逻服务。“转包”治安权这一事件说明了：", "options": ["因地制宜地维护治安是政府的基本职责", "保安巡逻是治安防控的协助力量", "社会治安需要综合治理", "某些行政执法部门缺乏法制观念，滥用权力"], "a": 3, "e": ".【D】宪政社会，公民向政府支付赋税，就是为了“购买”包括警察在内的政府部门的公共安全与服务，如果这种安全与服务可以转包，警察存在的合法性便无存。即便是协议下的转包，承包方也不能获得执法权主体资格。执法权是公民以立法的方式授予政府部门，在未取得公民同意的情况下不能转嫁给另一方，否则即是一种渎职。故正确答案为D。", "tag": "法律常识"},
{"id": "law-398", "q": "“徒法不足以自行”这句话表明：", "options": ["法律是由社会物质生活条件决定的", "在正式公布之前，法律不会自己生效", "法律的作用是有局限的", "法律永远不能满足人类的需要"], "a": 2, "e": ".【C】“徒善不足以为政，徒法不足以自行”的意思是只有善德不足以处理国家的政务，只有法令不能够使之自己发生效力。意为治理国家必须把行善政与行法令结合起来，说明法律的作用是有“局限性”的。故正确答案为C。", "tag": "法律常识"},
{"id": "law-399", "q": "根据我国的法律效力层次，下列法律中效力最高的是：", "options": ["行政法规", "地方性法规", "政府规章", "自治条例"], "a": 0, "e": ".【A】根据《宪法》和《立法法》的规定，行政法规的效力高于地方性法规、规章。地方性法规的效力高于本级和下级地方政府规章，其中省、自治区的人民代表大会及其常务委员会制定的地方性法规的效力又高于本行政区域内的较大的市的人民代表大会及其常务委员会制定的地方性法规。故正确答案为A。本题相关知识点：根据《宪法》和《立法法》的规定，在中国的法律效力等级体系中，宪法具有最高的法律效力，一切法律、行政法规、地方性法规、自治条例和单行条例、规章都不得同宪法相抵触。宪法的法律效力高于行政法规、地方性法规、规章。其中基本法律的效力又高于基本法律以外的法律。", "tag": "法律常识"},
{"id": "law-400", "q": "下列法系中对世界法影响最大的是：", "options": ["印度法系", "中华法系", "大陆法系", "非洲法系"], "a": 2, "e": ".【C】世界五大法系分别为大陆法系、英美法系、伊斯兰法系、印度法系和中华法系。印度法系是公元5-7世纪以前古印度奴隶制法和以其为基础的古缅甸、暹罗、锡兰、菲律宾等国法律的统称。当今印度法系已经成为历史名词，但在习惯中有部分遗迹可循。中华法系是中国古代封建法律和亚洲一些仿效这种法律的国家，如日本、朝鲜等国家法律的总称。它始于秦代，到隋唐时期成熟。清末由于现代司法制度的引入而解体。大陆法系，又称民法法系、罗马—日尔曼法系或成文法系。在西方法学著作中多称民法法系，它是包括欧洲大陆大部分国家从19世纪初以罗马法为基础建立起来的、以1804年《法国民法典》和1896年《德国民法典》为代表的法律制度以及其他国家或地区效仿这种制度而建立的法律制度，也是西方国家中与英美法系并列的渊源久远和影响较大的法系，C正确。选项D并不存在，属于干扰项。故正确答案为C。", "tag": "法律常识"},
{"id": "law-401", "q": "法治国家要求形成独立、合理的法律：", "options": ["司法权", "决策机制", "执行机构", "运行机制"], "a": 3, "e": ".【D】在法治国家中，法律要实现其社会功能，就要首先形成独立合理的运行机制。建立独立的法律运行机制，要求法律系统必须具有相对独立性，具有自己特定的形式要件和运行目标。故正确答案为D。", "tag": "法律常识"},
{"id": "law-402", "q": "下列哪一条不属于我国制定法律的基本原则？", "options": ["以事实为依据", "公民在法律面前一律平等", "灵活性与原则性相结合"], "a": 1, "e": ".【B】本题考查法律常识，主要涉及法的制定的基本原则。法的制定的基本原则，是在法的制定的整个活动中贯彻始终的行为准则，它是指导思想的规范化和具体化，是指导思想体现的形式和落实的保证。我国制定法律的基本原则，一般来说要遵循以下基本原则：（一）实事求是，一切从实际出发的原则；（二）合宪性和法制统一原则；（三）总结国内实践经验和借鉴外国经验相结合的原则；（四）原则性和灵中相结合的原则；（七）维护法的稳定性、连续性和严肃性与及时创、改、废相结合的原则。ACD项正确，均属于我国制定法律的基本原则。B项错误，“公民在法律面前一律平等”属于我国法律的适用原则，而不是立法的基本原则。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-403", "q": "“公民在法律面前人人平等”可以做出如下理解：", "options": ["公民的立法平等", "公民在立法、执法、守法上一律平等", "公民的执法平等", "公民在法律的适用上一律平等"], "a": 3, "e": ".【D】本题考查法律常识。AB项错误，公民在立法上是不平等的。因为法律体现的是统治阶级的意志，被统治阶级没有资格立法。C项错误，公民自身没有执法权，公民在执法面前一律平等指的是公民作为执法的对象一律平等。D项正确，根据《宪法》第三十三条第二款的规定：“中华人民共和国公民在法律面前一律平等。”公民在法律面前一律平等主要指的是公民在适用法律上一律平等，任何人没有超越法律的特权。故正确答案为D。", "tag": "法律常识"},
{"id": "law-404", "q": "垄断协议分为横向垄断协议和纵向垄断协议。下列哪一垄断协议与其他三项不同？", "options": ["甲市销售额排名前五的手机销售门店召开会议，指定下半年各类手机产品的最低价格", "乙市四家最大的面包店把全市五十家面包店组织在一起，协议指定采购某品牌面粉", "丙市七家米粉厂互相约定，各米粉厂只能在划定的区域内销售米粉", "丁市某电器生产公司和八家电器销售公司约定对外批发电器的销售价格"], "a": 3, "e": ".【D】本题考查法律常识。根据《中华人民共和国反垄断法》第十三条规定：“禁止具有竞争关系的经营者达成下列垄断协议：（一）固定或者变更商品价格；（二）限制商品的生产数量或者销售数量；（三）分割销售市场或者原材料采购市场；（四）限制购买新技术、新设备或者限制开发新技术、新产品；（五）联合抵制交易；（六）国务院反垄断执法机构认定的其他垄断协议。本法所称垄断协议，是指排除、限制竞争的协议、决定或者其他协同行为。”根据该法第十四条规定：“禁止经营者与交易相对人达成下列垄断协议：（一）固定向第三人转售商品的价格；（二）限定向第三人转售商品的最低价格；（三）国务院反垄断执法机构认定的其他垄断协议。”横向垄断协议即《中华人民共和国反垄断法》第十三条规定的情形，是指具有竞争关系的经营者达成的协议，典型的横向垄断协议包括固定价格、限定产量、划分市场、联合抵制等。纵向垄断协议即《中华人民共和国反垄断法》第十四条规定的情形，是指两个或两个以上在同一产业中处于不同阶段而有买卖关系的企业间的垄断协议，典型的纵向垄断协议包括维持转售价格协议和独家销售协议等。A项中甲市排名前五的手机销售门店是具有竞争关系的经营者，达成的指定各类手机产品最低销售价格的协议属于横向垄断协议。B项中乙市四家最大面包店与其他五十家面包店是具有竞争关系的经营者，达成的采购某品牌面粉的协议属于横向垄断协议。C项中丙市七家米粉厂是具有竞争关系的经营者，达成的在划定区域内销售米粉的协议属于横向垄断协议。D项中丁市某电器生产公司和八家电器销售公司是有买卖关系的企业，达成的对外批发电器销售价格的协议属于纵向垄断协议。故正确答案为D。", "tag": "法律常识"},
{"id": "law-405", "q": "下列与某食品厂相关的做法不符合食品安全法规定的是：", "options": ["该厂无需为食品安全风险评估付费", "该厂退休职工有权举报食品安全违法行为", "该厂配备了兼职的食品安全专业技术人员", "食品安全风险监测工作人员到该厂采集样品无需支付费用"], "a": 3, "e": ".【D】《食品安全法》第六十条规定，县级以上质量监督、工商行政管理、食品药品监督管理部门应当对食品进行定期或者不定期的抽样检验。进行抽样检验，应当购买抽取的样品。而D项是“采集样品无需支付费用”，是错误的做法。其他选项都是正确的做法。本题是选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-406", "q": "下列条款符合法律规定的是：", "options": ["某饭店店堂告知：“请保管好随身物品，丢失概不负责”", "某干洗店申明：衣物丢失，只赔付洗衣费二倍的价钱", "淘宝网某服饰店表示：本店商品一经售出，概不退货", "某商场厕所门口警示牌“地滑小心摔倒，否则概不负责任”"], "a": 0, "e": ".【A】《消费者权益保护法》第二十六条规定：经营者不得以格式条款、通知、声明、店堂告示等方式，作出排除或者限制消费者权利、减轻或者免除经营者责任、加重消费者责任等对消费者不公平、不合理的规定，不得利用格式条款并借助技术手段强制交易。格式条款、通知、声明、店堂告示等含有前款所列内容的，其内容无效，B项不符合法律规定，排除。《消费者权益保护法》第24条规定，经营者提供的商品或者服务不符合质量要求的，消费者可以依照国家规定、当事人约定退货，或者要求经营者履行更换、修理等义务。没有国家规定和当事人约定的，消费者可以自收到商品之日起七日内退货；七日后符合法定解除合同条件的，消费者可以及时退货，不符合法定解除合同条件的，可以要求经营者履行更换、修理等义务。《消费者权益保护法》第26条规定，经营者不得以格式条款、通知、声明、店堂告示等方式，作出排除或者限制消费者权利、减轻或者免除经营者责任、加重消费者责任等对消费者不公平、不合理的规定，不得利用格式条款并借助技术手段强制交易，C项不符合法律规定，排除。《最高人民法院关于审理人身损害赔偿案件适用法律若干问题的解释》第六条规定：从事住宿、餐饮、娱乐等经营活动或者其他社会活动的自然人、法人、其他组织，未尽合理限度范围内的安全保障义务致使他人遭受人身损害，赔偿权利人请求其承担相应赔偿责任的，人民法院应予支持。D项不符合法律规定，排除。故正确答案为A。", "tag": "法律常识"},
{"id": "law-407", "q": "消费者权利是消费者在购买、使用商品或者接受服务中所享有的权利。下列消费者权利与侵犯该权利的事件对应正确的是（）。", "options": ["知情权——某线上服装店为快速清仓，推出低价“福袋”商品，并注明“福袋”内服装的款式、颜色等随机搭配", "自主选择权——某餐厅推出外卖8 折活动，但是消费者点外卖时只有选择套餐才享受折扣，自由搭配时无法享受8 折", "安全保障权——王某的轿车已达到报废标准，但是他依旧照常使用，在一次高速行驶中刹车失灵造成事故", "公平交易权——李某在车行订购汽车后，车行要求李某购买“车辆维护套餐”，否则汽车不予交付"], "a": 3, "e": ".【D】本题考查法律常识。A项错误，根据《消费者权益保护法》第八条规定可知：“消费者享有知悉其购买、使用的商品或者接受的服务的真实情况的权利。消费者有权根据商品或者服务的不同情况，要求经营者提供商品的价格、产地、生产者、用途、性能、规格、等级、主要成份、生产日期、有效期限、检验合格证明、使用方法说明书、售后服务，或者服务的内容、规格、费用等有关情况。”消费者已经知晓“福袋”内的商品颜色、样式是随机搭配的，消费者已经知情。B项错误，根据《消费者权益保护法》第九条规定可知：“消费者享有自主选择商品或者服务的权利。消费者有权自主选择提供商品或者服务的经营者，自主选择商品品种或者服务方式，自主决定购买或者不购买任何一种商品、接受或者不接受任何一项服务。消费者在自主选择商品或者服务时，有权进行比较、鉴别和挑选。”餐厅对外卖套餐8折促销，未侵犯消费者的自主选择权。C项错误，根据《消费者权益保护法》第七条第二款规定可知：“消费者有权要求经营者提供的商品和服务，符合保障人身、财产安全的要求。”王某的轿车并非在购买的时候存在质量问题，经营者未侵犯王某的安全保障权。D项正确，根据《消费者权益保护法》第十条规定可知：“消费者享有公平交易的权利。消费者在购买商品或者接受服务时，有权获得质量保障、价格合理、计量正确等公平交易条件，有权拒绝经营者的强制交易行为。”车行要求李某购买“车辆维护套餐”，否则汽车不予交付，是捆绑销售行为，侵犯的是李某的公平交易权。故正确答案为D。", "tag": "法律常识"},
{"id": "law-408", "q": "下列情形符合我国法律规定的是：", "options": ["某地消费者协会宣传并销售本地的特色产品", "根据产品质量法，制冷效果不好的空调属于“缺陷产品”", "张阿姨在网上超市买了生鲜食品，收货后可在7 天内无理由退款", "某问题奶粉导致数名婴儿患肾结石，代言该奶粉的明星需承担连带责任"], "a": 3, "e": ".【D】本题考查法律常识。A项错误，根据《消费者权益保护法》第三十七条第一款规定：“消费者协会履行下列公益性职责：（一）向消费者提供消费信息和咨询服务，提高消费者维护自身合法权益的能力，引导文明、健康、节约资源和保护环境的消费方式；（二）参与制定有关消费者权益的法律、法规、规章和强制性标准；（三）参与有关行政部门对商品和服务的监督、检查；（四）就有关消费者合法权益的问题，向有关部门反映、查询，提出建议；（五）受理消费者的投诉，并对投诉事项进行调查、调解；（六）投诉事项涉及商品和服务质量问题的，可以委托具备资格的鉴定人鉴定，鉴定人应当告知鉴定意见；（七）就损害消费者合法权益的行为，支持受损害的消费者提起诉讼或者依照本法提起诉讼；（八）对损害消费者合法权益的行为，通过大众传播媒介予以揭露、批评。”消费者协会不可宣传并销售本地的特色产品。B项错误，根据《产品质量法》第四十六条规定：“本法所称缺陷，是指产品存在危及人身、他人财产安全的不合理的危险；产品有保障人体健康和人身、财产安全的国家标准、行业标准的，是指不符合该标准。”制冷效果不好的空调是瑕疵产品而非缺陷产品。C项错误，《消费者权益保护法》第二十五条第一款规定：“经营者采用网络、电视、电话、邮购等方式销售商品，消费者有权自收到商品之日起七日内退货，且无需说明理由，但下列商品除外：（一）消费者定作的；（二）鲜活易腐的；（三）在线下载或者消费者拆封的音像制品、计算机软件等数字化商品；（四）交付的报纸、期刊。”生鲜食品不可七日无理由退货。D项正确，根据《广告法》第五十六条第二款规定：“关系消费者生命健康的商品或者服务的虚假广告，造成消费者损害的，其广告经营者、广告发布者、广告代言人应当与广告主承担连带责任。”明星代言有问题的奶粉，造成消费者损害的，应承担连带责任。故正确答案为D。", "tag": "法律常识"},
{"id": "law-409", "q": "李某认为某电商平台上的商户所销售服装的外观侵害了其设计著作权，于是通知电商平台对该商户采取删除、屏蔽、断开链接、终止交易和服务等措施。关于李某的上述通知，下列说法正确的是：", "options": ["李某只需要提出主张，无须举证，举证商户是否侵权的责任由电商平台和商户承担", "李某通知错误，造成商户损失的，李某应当加倍赔偿商户损失", "李某必须提供商户侵权的确切证据", "李某必须提供商户侵权的初步证据"], "a": 3, "e": ".【D】本题考查法律常识。根据《电子商务法》第四十二条规定：“知识产权权利人认为其知识产权受到侵害的，有权通知电子商务平台经营者采取删除、屏蔽、断开链接、终止交易和服务等必要措施。通知应当包括构成侵权的初步证据。电子商务平台经营者接到通知后，应当及时采取必要措施，并将该通知转送平台内经营者；未及时采取必要措施的，对损害的扩大部分与平台内经营者承担连带责任。因通知错误造成平台内经营者损害的，依法承担民事责任。恶意发出错误通知，造成平台内经营者损失的，加倍承担赔偿责任。”A项错误，李某作为知识产权权利人认为其知识产权受到侵害提出主张，需要举证。B项错误，恶意发出错误通知，造成平台内经营者损失的，才是加倍承担赔偿责任。C项错误，D项正确，通知应当包括的是侵权的初步证据，不是确切证据。故正确答案为D。", "tag": "法律常识"},
{"id": "law-410", "q": "老丁将自家临街的一间房屋改为商店，里面的一间房屋用于居住，并办理了合法经营手续。前不久，有消费者举报老丁商店有假冒商品出售，经查，举报属实。对此，市场监督管理部门可以作出的行为是", "options": ["查封商店并扣留假冒商品", "冻结商店或老丁的银行账户", "没收商店的营业收入", "责令老丁暂停营业"], "a": 3, "e": ".【D】本题考查法律常识。根据《消费者权益保护法》第五十六条规定：“经营者有下列情形之一，除承担相应的民事责任外，其他有关法律、法规对处罚机关和处罚方式有规定的，依照法律、法规的规定执行；法律、法规未作规定的，由工商行政管理部门或者其他有关行政部门责令改正，可以根据情节单处或者并处警告、没收违法所得、处以违法所得一倍以上十倍以下的罚款，没有违法所得的，处以五十万元以下的罚款；情节严重的，责令停业整顿、吊销营业执照：（二）在商品中掺杂、掺假，以假充真，以次充好，或者以不合格商品冒充合格商品的”AB项错误，采用查封、扣押、冻结等行政强制措施是对财物实施暂时性控制，而老丁商店销售假冒商品已经查证属实，市场监督管理部门应当直接做出行政处罚，而非采取行政强制措施。C项错误，市场监督管理部门可以做出没收违法所得的处罚，但不得没收商店的营业收入。D项正确，如果情节严重，市场监督管理部门可以做出责令暂停营业的处罚。故正确答案为D。", "tag": "法律常识"},
{"id": "law-411", "q": "按照我国《食品安全法》的规定，下列保健食品的说明书符合要求的是：", "options": ["某益生菌说明书称可根治便秘", "某枇杷糖说明书称可预防咽喉炎", "某维生素片说明书称具有较强保健功能", "某降糖茶说明书称可替代部分药物使用"], "a": 2, "e": ".【C】本题考查法律常识。《食品安全法》第七十八条规定：“保健食品的标签、说明书不得涉及疾病预防、治疗功能，内容应当真实，与注册或物’。保健食品的功能和成分应当与标签、说明书相一致。”A项错误，保健食品说明书不得涉及治疗功能，益生菌说明书上称可根治便秘不符合法律规定。B项错误，保健食品说明书不得涉及疾病预防，枇杷糖说明书上称可预防咽喉炎不符合法律规定。C项正确，某维生素说明书上称具有较强保健功能是符合法律规定的，可载明。D项错误，保健食品说明书上必须声明“本品不能代替药物”，降糖茶说明书上载明的该句话违反法律规定。故正确答案为C。", "tag": "法律常识"},
{"id": "law-412", "q": "张某在某电子商务平台定做了一张沙发，购买了一盏台灯、一台热水器和一台燃气灶。下列情形中，不符合法律规定的是", "options": ["张某自收到沙发之日起七日内有权退货，且无需说明理由", "张某购买的台灯被快递公司丢失，有权要求卖方重新发货", "张某因热水器缺陷而受伤，有权向生产者或销售者请求赔偿", "张某购买的燃气灶为冒牌货，有权要求平台提供卖方的信息"], "a": 0, "e": ".【A】本题考查法律常识。A项错误，根据《消费者权益保护法》第二十五条第一款规定：“经营者采用网络、电视、电话、邮购等方式销售商品，消费者有权自收到商品之日起七日内退货，且无需说明理由，但下列商品除外：（一）消费者定作的；（二）鲜活易腐的；（三）在线下载或者消费者拆封的音像制品、计算机软件等数字化商品；（四）交付的报纸、期刊。”故定做的沙发不适用“七日无理由退货”。B项正确，根据《电子商务法》第二十条规定：“电子商务经营者（指通过电子商务平台销售商品或者提供服务的电子商务经营者）应当按照承诺或者与消费者约定的方式、时限向消费者交付商品或者服务，并承担商品运输中的风险和责任。但是，消费者另行选择快递物流服务提供者的除外。”故该项中台灯丢失风险应由卖方承担，故张某有权要求卖方重新发货。C项正确，根据《消费者权益保护法》第四十条第二款规定：“消费者或者其他受害人因商品缺陷造成人身、财产损害的，可以向销售者要求赔偿，也可以向生产者要求赔偿。属于生产者责任的，销售者赔偿后，有权向生产者追偿。属于销售者责任的，生产者赔偿后，有权向销售者追偿。”D项正确，根据《消费者权益保护法》第四十四条规定：“消费者通过网络交易平台购买商品或者接受服务，其合法权益受到损害的，可以向销售者或者服务者要求赔偿。网络交易平台提供者不能提供销售者或者服务者的真实名称、地址和有效联系方式的，消费者也可以向网络交易平台提供者要求赔偿。”张某购买的燃气灶为冒牌货，其合法权益已受到损害，有权要求平台提供卖方的信息。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-413", "q": "下列各类收入（收益）中，无需缴纳个人所得税的是（）。", "options": ["居民个人购买国债所获得相应利息", "文章作者去世后财产继承人取得的遗作稿酬", "个体工商户销售服装所取得的收入", "受雇从事公益性医疗服务所取得的报酬"], "a": 0, "e": ".【A】本题考查法律常识。根据《个人所得税法》第二条第一款规定：“下列各项个人所得，应当缴纳个人所得税：（一）工资、薪金所得；（二）劳务报酬所得；（三）稿酬所得；（四）特许权使用费所得；（五）经营所得；（六）利息、股息、红利所得；（七）财产租赁所得；（八）财产转让所得；（九）偶然所得。”A项正确，根据《个人所得税法》第四条第一款规定：“下列各项个人所得，免征个人所得税：（二）国债和国家发行的金融债券利息。”居民个人购买国债所获得相应利息属于此列，不需要缴纳个人所得税。B项错误，文章作者去世后财产继承人取得的遗作稿酬属于稿酬所得，需要缴纳个人所得税。C项错误，个体工商户销售服装所取得的收入属于经营所得，需要缴纳个人所得税。D项错误，受雇从事公益性医疗服务所取得的报酬属于工资、薪金所得，需要缴纳个人所得税。故正确答案为A。", "tag": "法律常识"},
{"id": "law-414", "q": "2014 年，万某开了一家网店，专门销售各类知名品牌的鞋服等商品，后经相关品牌的权利人发现并鉴定万某销售的商品均系仿冒其注册商标的产品。在上述案例中，相关知名品牌的权利人不可以：", "options": ["要求工商部门对万某的行为进行查处", "没收万某销售的侵权商品", "向法院起诉主张赔偿", "与万某进行协商解决"], "a": 1, "e": ".【B】本题主要考查法律常识。根据《反不正当竞争法》第六条规定：“经营者不得实施下列混淆行为，引人误认为是他人商品或者与他人存在特定联系：（一）擅自使用与他人有一定影响的商品名称、包装、装潢等相同或者近似的标识；（二）擅自使用他人有一定影响的企业名称（包括简称、字号等）、社会组织名称（包括简称等）、姓名（包括笔名、艺名、译名等）；（三）擅自使用他人有一定影响的域名主体部分、网站名称、网页等；（四）其他足以引人误认为是他人商品或者与他人存在特定联系的混淆行为。”本题中，该网店仿冒他人注册商标产品的行为，构成混淆行为。A项正确，相关知名品牌权利人作为受害者，有权要求工商部门对万某的行为进行查处，防止万某继续实施侵害其合法权益。B项错误，《反不正当竞争法》第十八条：“经营者违反本法第六条规定实施混淆行为的，由监督检查部门责令停止违法行为，没收违法商品。”本案中，相关知名品牌的权利人无权没收万某销售的侵权商品，应当由监督检查部门没收违法商品。C项正确，《反不正当竞争法》第十七条第二款规定：“经营者的合法权益受到不正当竞争行为损害的，可以向人民法院提起诉讼。”D项正确，相关知名品牌的权利人与万某属于民商事纠纷，可以进行协商以解决纠纷。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-415", "q": "关于税收，下列说法错误的是：", "options": ["涉及税收的制度只能由法律来规定", "履行纳税义务是公民享有其他权利的前提条件", "企业在缴纳增值税时应当扣除企业的经营成本", "小王抽奖获得的10 万元奖金应当缴纳个人所得税"], "a": 1, "e": ".【B】本题考查经济法常识，主要涉及税收的相关内容。A项正确，《立法法》第八条规定：“下列事项只能制定法律：（六）税种的设立、税率的确定和税收征收管理等税收基本制度。”B项错误，《宪法》第五十六条规定：“中华人民共和国公民有依照法律纳税的义务。”依法纳税是公民应该履行的一项基本义务。纳税义务的履行，实际上也为纳税人带来相应的权利。纳税者有权享受政府提供的各种公共和服务设施，如医疗、教育、社会安全、法律保障、交通等，并有权要求政府积极改善这些条件并提供优质服务。从某种意义上说，纳税义务的履行是纳税者享有权利的基础与条件。但这并不表示纳税是公民享有其他权利的前提，比如选举权、人身自由权等。C项正确，从计税原理上说，增值税是对商品生产、流通、劳务服务中多个环节的新增价值或商品的附加值征收的一种流转税。企业的经营成本也是商品的成本，不属于新增价值，所以在缴税时应该扣除。D项正确，《中华人民共和国个人所得税法》第二条规定：“下列各项个人所得，应纳个人所得税：十、偶然所得；。”《中华人民共和国个人所得税法实施条例》第八条第（十）项规定：“偶然所得，是指个人得奖、中奖、中彩以及其他偶然性质的所得。”同时，国税发（1994）127号、财税字（1998）012号文件规定，个人购买社会福利有奖募捐奖券、体育彩票，凡一次中奖收入不超过1万元的暂免征收个人所得税，超过1万元的应按规定征收个人所得税。小王抽奖获得的10万元奖金，多于1万元，应当缴纳个人所得税。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-416", "q": "某面馆每位服务员胸前都佩戴一个牌子，上面印有二维码，并写着“感谢打赏3 元”的字样。每当顾客用完餐结账时，服务员就会建议顾客扫码打赏。从法律角度看，这种扫码打赏属于：", "options": ["侵犯了消费者的合法权益", "消费者的道德义务", "赠与行为", "不合法的变相收费"], "a": 2, "e": ".【C】本题考查法律常识。A、D两项错误，该面馆的服务员只是“建议”顾客扫码打赏，消费者可以自由选择打赏或者不打赏，因此，该行为并没有损害消费者的合法权益，也不属于不合法的变相收费。B项错误，消费者没有义务必须对服务员进行打赏。C项正确，赠与行为是指赠与人将自己的财产无偿给予受赠人，而受赠人愿意接受赠与。本题中，消费者如果自愿扫码打赏，属于将自己的财产赠与服务员，因此法律上属于赠与行为。故正确答案为C。", "tag": "法律常识"},
{"id": "law-417", "q": "村民孙某早年到城里打工并购买了住房，遂将农村的房屋卖掉。随着年岁的增长，孙某打算回乡养老，欲再申请宅基地建房。对此，下列说法正确的是（）。", "options": ["县政府不应批准孙某的宅基地申请", "县政府在孙某出售城市住房后可批准其申请", "县政府在孙某补交旧宅基地的使用费后可批准其申请", "县政府在孙某缴纳新宅基地的使用费后可批准其申请"], "a": 0, "e": ".【A】本题主要考查经济类法律常识。根据我国《土地管理法》第六十二条规定：“农村村民一户只能拥有一处宅基地，其宅基地的面积不得超过省、自治区、直辖市规定的标准。农村村民出卖、出租住房后，再申请宅基地的，不予批准。”题干中，村民孙某已经将农村的房屋卖掉，后回乡养老想要再申请宅基地，不应予以批准，因此B、C、D三项错误。故正确答案为A。", "tag": "法律常识"},
{"id": "law-418", "q": "在股份制公司，大股东凭借所占的多数股权影响公司决策，维护自己的利益，而众多的中小股东则可以通过由律师、学者等非投资人担任的（）在董事会维护自己的利益。", "options": ["机构监管人", "独立董事", "监事", "职业经理人"], "a": 1, "e": ".【B】本题考查法律常识。B项正确、A、C、D三项错误，根据证监会《关于在上市公司建立独立董事制度的指导意见》（证监发〔2001〕102号）：“独立董事应当按照相关法律法规、本指导意见和公司章程的要求，认真履行职责，维护公司整体利益，尤其要关注中小股东的合法权益不受损害。”，独立董事不得由投资人担任，并与其所受聘的上市公司及其主要股东不存在可能妨碍其进行独立客观判断的关系。故正确答案为B。", "tag": "法律常识"},
{"id": "law-419", "q": "赵某逛电器商场，准备购买一台豆浆机，其享有的权利不包括：", "options": ["人身、财产安全不受损害的权利", "选择购买何种品牌豆浆机的权利", "拒绝保安因商场失窃而提出搜查其背包的权利", "购买一台低价促销、有轻微划痕的豆浆机，一个月后以商品存在瑕疵为由提出退款的权利"], "a": 3, "e": ".【D】D项符合题意，《消费者权益保护法》第23条规定：经营者应当保证在正常使用商品或者接受服务的情况下其提供的商品或者服务应当具有的质量、性能、用途和有效期限；但消费者在购买该商品或者接受该服务前已经知道其存在瑕疵，且存在该瑕疵不违反法律强制性规定的除外。A项不符合题意：《消费者权益保护法》第七条：消费者在购买、使用商品和接受服务时享有人身、财产安全不受损害的权利。B项不符合题意：《消费者权益保护法》第九条：消费者享有自主选择商品或者服务的权利。C项不符合题意：《消费者权益保护法》第二十七条：经营者不得对消费者进行侮辱、诽谤，不得搜查消费者的身体及其携带的物品，不得侵犯消费者的人身自由。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-420", "q": "下列关于有限责任公司治理结构的说法不正确的是：", "options": ["一般情况下股东会由董事会或执行董事负责召开", "经理由股东会任命和解聘，对股东会负责", "监事不得由董事和高级管理人员兼任", "股东会是公司的权力机构"], "a": 1, "e": ".【B】A选项正确，根据《公司法》第40条第一二款规定：“有限责任公司设立董事会的，股东会会议由董事会召集，董事长主持；董事长不能履行职务或者不履行职务的，由副董事长主持；副董事长不能履行职务或者不履行职务的，由半数以上董事共同推举一名董事主持。有限责任公司不设董事会的，股东会会议由执行董事召集和主持。B选项错误，根据《公司法》第49条规定：“有限责任公司可以设经理，由董事会决定聘任或者解聘。经理对董事会负责，行使下列职权“C选项正确，根据《公司法》第51条第四款规定：“董事、高级管理人员不得兼任监事。”D选项正确，根据《公司法》第36条规定：“有限责任公司股东会由全体股东组成。股东会是公司的权力机构，依照本法行使职权。”本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-421", "q": "今年3 月，小李在某网站购买了五盒某明星代言的药品，收到后发现药品为假药。小李找到该网站，该网站却不能提供该药品生产者的真实名称、地址和联系方式。这时小李该如何维权（）。", "options": ["要求网站、代言明星都承担责任，法院均应支持", "要求网站承担责任，法院也应支持", "要求代言明星承担责任，法院也应支持", "要求网站、代言明星都承担责任，法院不支持小李对代言明星追责的要求"], "a": 0, "e": ".【A】根据《消费者权益保护法》第四十五条规定：消费者因经营者利用虚假广告或者其他虚假宣传方式提供商品或者服务，其合法权益受到损害的，可以向经营者要求赔偿。广告经营者、发布者发布虚假广告的，消费者可以请求行政主管部门予以惩处。广告经营者、发布者不能提供经营者的真实名称、地址和有效联系方式的，应当承担赔偿责任。广告经营者、发布者设计、制作、发布关系消费者生命健康商品或者服务的虚假广告，社会团体或者其他组织、个人在关系消费者生命健康商品或者服务的虚假广告或者其他虚假宣传中向消费者推荐商品或者服务，造成消费者损害的，应当与提供该商品或者服务的经营者承担连带责任。故正确答案为A。", "tag": "法律常识"},
{"id": "law-422", "q": "关于知识产权，说法错误的是：", "options": ["具有专用性、时间性、地域性", "仅包括财产权的内容而不涉及人身权", "必须具有首创性、新颖性", "必须有能为人感知的客观表现形式"], "a": 1, "e": ".【B】知识产权具有双重性：既有某种人身权（如签名权）的性质，又包含财产权的内容。但商标权是一个例外，它只保护财产权，不保护人身权。故正确答案为B。拓展：知识产权的特征概括起来有以下几个：（1）无形财产权。（2）确认或授予必须经国家专门立法直接规定。（3）双重性：既有某种人身权（如签名权）的性质，又包含财产权的内容。但商标权是一个例外，它只保护财产权，不保护人身权。（4）专有性：知识产权为权利主体所专有。权利人以外的任何人，未经权利人同意或者法律的特别规定，都不能享有或者使用这种权利。（5）地域性：某一国法律所确认和保护的知识产权，只在该国领域内发生法律效力。（6）时间性：法律对知识产权的保护规定一定的保护期限，知识产权只在法定期限内有效。", "tag": "法律常识"},
{"id": "law-423", "q": "当事人因以下协议发生争议，不能适用合同法的是：", "options": ["商品房买卖协议", "收养协议", "赠与协议", "政府采购协议"], "a": 1, "e": ".【B】本题考查法律常识，主要涉及《中华人民共和国合同法》相关内容。A项表述正确：商品房买卖协议属于《中华人民共和国合同法》中的买卖合同，排除。B项表述错误：《中华人民共和国合同法》第二条规定：“本法所称合同是平等主体的自然人、法人、其他组织之间设立、变更、终止民事权利义务关系的协议。婚姻、收养、监护等有关身份关系的协议，适用其他法律的规定。”当选。C项表述正确：赠与协议属于《中华人民共和国合同法》中的赠与合同，排除。D项表述正确：《中华人民共和国政府采购法》第四十三条第一款规定：“政府采购合同适用合同法。采购人和供应商之间的权利和义务，应当按照平等、自愿的原则以合同方式约定。”排除。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-424", "q": "下列行为侵犯到他人知识产权的是：", "options": ["甲模仿某知名作家的写作风格创作小说并以该作家名字公开发表", "甲因无法分辨真假销售某高仿皮具，但未给商标权利人造成损失", "甲开发“A 之C”游戏并公开销售，但“AC”商标的权利人是乙", "甲申请注册“AC”琴行，“AC”二字与某知名电脑商标完全重合"], "a": 1, "e": ".【B】A项为强干扰项，甲侵犯的是知名作家的姓名权，并不构成侵犯他人知识产权。B项正确，《商标法》第六十四条第二款规定：“销售不知道是侵犯注册商标专用权的商品，能证明该商品是自己合法取得并说明提供者的，由工商行政管理部门责令停止销售，不承担赔偿责任。”本题中，无法分辨真假，且未给商标权利人造成损失，仅仅表明其不承担赔偿责任，但这并不意味着其不构成侵权，应当停止销售。C项不选，“A之C”与“AC”商标区别明显，不构成侵权。D项不选，甲申请注册“AC”琴行，仅仅是“申请注册”，并未实质侵犯某知名电脑商标持有人的权利。其次，商标注册也区分类别，琴行与电脑商标属于不同类别。因此不构成侵权。故正确答案为B。", "tag": "法律常识"},
{"id": "law-425", "q": "某公司占据家具制造业70%的市场份额，下列行为不属于滥用市场支配地位的是：", "options": ["以不公平的高价销售沙发", "没有正当理由，以低于成本的价格销售衣橱", "没有正当理由，在销售写字台时搭售电脑桌", "与第二大家具制造商协商协定提高实木家具价格"], "a": 3, "e": ".【D】根据《反垄断法》第17条第一项、第二项和第五项的规定：“禁止具有市场支配地位的经营者从事下列滥用市场支配地位的行为：以不公平的高价销售商品或者不公平的低价购买商品；没有正当理由，以低于成本的价格销售商品；没有正当理由搭售商品，或者在交易时附加其他不合理的交易条件。”所以只有选项D不属于滥用市场支配地位的行为。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-426", "q": "某公司由甲、乙、丙三位股东出资设立，丁和戊分别被依法选为公司的执行董事和监事，该公司因经营不善而无法按期偿还银行贷款。根据法律规定，下述主张能获得支持的是：", "options": ["银行要求作出贷款决策的丁返还贷款", "银行要求该公司返还贷款", "银行要求已足额缴纳出资的甲、乙、丙三股东返还贷款", "银行要求对该公司承担监督检查责任的戊返还贷款"], "a": 1, "e": ".【B】《公司法》第3条规定：“公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。”因此，银行可以要求该公司返还贷款。故正确答案为B。", "tag": "法律常识"},
{"id": "law-427", "q": "甲、乙、丙为某合伙企业的合伙人，后该合伙企业经营亏损，财产不足以清偿到期债务。根据《中华人民共和国合伙企业法》规定，甲、乙、丙对该债务应承担：", "options": ["无限责任", "按份责任", "无限连带责任", "有限连带责任"], "a": 2, "e": ".【C】根据《合伙企业法》第三十九条规定：“合伙企业对其债务，应先以其全部财产进行清偿。合伙企业财产不足清偿到期债务的，各合伙人应当承担无限连带清偿责任。”这一规定确立了合伙企业债务责任的基本原则和形式。因此甲、乙、丙作为合伙人应该承担无限连带清偿责任。故正确答案为C。本题相关知识点：无限连带责任：每个合伙人对于合伙债务都负有全部清偿的义务，而合伙的债权人也有权向合伙人中的任何一人或数人要求其清偿债务的一部分或全部。", "tag": "法律常识"},
{"id": "law-428", "q": "根据《产品质量法》，下列说法正确的是：", "options": ["装修材料、建设工程的质量都可以适用该法", "对产品质量的监督检查以抽查为主要方式", "产品的生产者或销售者承担检验费用", "因产品存在缺陷造成损害要求赔偿的诉讼时效期间为一年"], "a": 1, "e": ".【B】A项错误，建筑工程质量并不适用于产品质量法。《产品质量法》第二条规定：建设工程不适用产品质量法的规定，但是，建设工程使用的建筑材料、建筑构配件和设备，属于规定的产品范围的，适用产品质量法规定；B项正确，《产品质量法》第十五条规定：国家对产品质量实行以抽查为主要方式的监督检查制度；C项错误，《产品质量法》第十五条规定：检验抽取样品的数量不得超过检验的合理需要，并不得向被检查人收取检验费用。监督抽查所需检验费用按照国务院规定列支；D项错误，《产品质量法》第四十五条规定：因产品存在缺陷造成损害要求赔偿的诉讼时效期间为二年，自当事人知道或者应当知道其权益受到损害时起计算。故正确答案为B。", "tag": "法律常识"},
{"id": "law-429", "q": "王某和张某分别出资5000 元和7000 元合开一个饭馆，后因经营不善欠债2000 元，对该债务双方应承担（）。", "options": ["无限连带责任", "无限按份责任", "有限连带责任", "有限按份责任"], "a": 0, "e": ".【A】本题考查经济法。根据《合伙企业法》第三十九条规定：“合伙企业对其债务，应先以其全部财产进行清偿。合伙企业财产不足清偿到期债务的，各合伙人应当承担无限连带清偿责任。”故正确答案为A。", "tag": "法律常识"},
{"id": "law-430", "q": "根据企业破产法律制度的规定，不属于破产费用的一项是：", "options": ["破产案件受理费", "债权人会议费", "清算组催收债务所需费用", "清算期间破产企业职工生活费"], "a": 3, "e": ".【D】《企业破产法》第四十一条规定：人民法院受理破产申请后发生的下列费用为破产费用：（1）破产案件的诉讼费用；（2）管理、变价和分配债务人财产的费用；（3）管理人执行职务的费用、报酬和聘用工作人员的费用。A、B、C三项均属于破产费用；D项的职工生活费不属于破产费用。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-431", "q": "个体户崔某为使自己的劣质酱油能在某超市上柜，为超市部门主管汤某安排一次全家境外游，并为汤某的儿子入学缴纳了3 万元的赞助费。在反不正当竞争法中这一行为属于：", "options": ["混淆行为", "虚假宣传行为", "独占排挤行为", "商业贿赂行为"], "a": 3, "e": ".【D】《反不正当竞争法》第八条规定：“经营者不得采用财物或者其他手段进行贿赂以销售或者购买商品”，其中所指的贿赂，既包括行贿也包括受贿。本题中崔某对汤某构成了行贿行为。故正确答案为D。", "tag": "法律常识"},
{"id": "law-432", "q": "下列情形属于我国行政复议受案范围的是：", "options": ["甲市公安局处理治安案件出具的调解书", "乙市人民政府对于确认矿藏所有权的决定", "丙市工商局对其工作人员作出的警告处分决定", "丁市人民政府颁布的地方政府规章《丁市城市市容管理规定》"], "a": 1, "e": ".【B】B项正确：根据《行政复议法》第六条规定：“有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：……（四）对行政机关作出的关于确认土地、矿藏、水流、森林、山岭、草原、荒地、滩涂、海域等自然资源的所有权或者使用权的决定不服的；……”因此，乙市人民政府对于确认矿藏所有权的决定属于我国行政复议受案范围，当选；A项错误：《行政复议法》第八条第二款规定：“不服行政机关对民事纠纷作出的调解或者其他处理，依法申请仲裁或者向人民法院提起诉讼。”因此，甲市公安局处理治安案件出具的调解书，不属于行政复议受案范围，排除；C项错误：《行政复议法》第八条第一款规定：“不服行政机关作出的行政处分或者其他人事处理决定的，依照有关法律、行政法规的规定提出申诉。”因此，丙市工商局对其工作人员作出的警告处分决定，不属于行政复议受案范围，排除；D项错误：根据《行政复议法》第七条的规定，公民、法人或者其他组织认为行政机关的具体行政行为所依据的国务院部、委员会规章和地方人民政府规章不合法时，应依照法律、行政法规办理对规章的审查，不属于行政复议受案范围，排除。故正确答案为B。", "tag": "法律常识"},
{"id": "law-433", "q": "某塑料厂职工丁某因公死亡，其近亲属可以依法从工伤保险基金领取：", "options": ["供养亲属抚恤金", "工伤医疗补助金", "伤残就业补助金", "生活护理费"], "a": 0, "e": ".【A】A项符合题意：我国《工伤保险条例》第三十九条规定：“职工因工死亡，其近亲属按照下列规定从工伤保险基金领取丧葬补助金、供养亲属抚恤金和一次性工亡补助金：……（二）供养亲属抚恤金按照职工本人工资的一定比例发给由因工死亡职工生前提供主要生活来源、无劳动能力的亲属。……”即职工因工死亡，使得由其提供主要生活来源、无劳动能力的亲属丧失了生活来源，基本生活难以维系，造成这种状况的直接原因就是工伤事故，因此其近亲属应当受到赔偿。B、C、D三项都属于工伤人员本人应获得的相关补助。故正确答案为A。", "tag": "法律常识"},
{"id": "law-434", "q": "下列处理问题的做法不符合我国相关法律法规的是：", "options": ["某公安局处长对本人被辞退的决定不服，当天即向法院提起行政诉讼", "某工商局科员拒不赡养父母，情节严重，单位给予其开除处分", "某省商务厅厅长退休后第二年到商务厅下属商贸公司任职，该省公务员主管部门责令其限期改正", "某税务局科长执行公务时，认为局长的决定有错误，向局长提出改正意见"], "a": 0, "e": ".【A】A项错误，“处长被辞退”是不可以提起行政诉讼的，因为行政机关对行政机关工作人员的奖惩、任免等决定是不属于人民法院的受案范围的。B项正确，科员拒不赡养父母，情节严重，已经构成“遗弃罪”，此时单位可以给予其“开除”处分。C项正确，商务厅厅长退休后第二年到商务厅下属的商贸公司任职，违反了“公务员辞去公职或者退休的，原系领导成员的公务员在离职三年内，其他公务员在离职两年内，不得到与原工作业务直接相关的企业或者其他营利性组织任职，不得从事与原工作业务直接相关的营利性活动”这一《公务员法》中的规定，该省公务员主管部门责令其限期改正是正确的做法。D项正确，公务员是有“对机关工作和领导人员提出批评和建议”的权利的，故科长向局长提出改正意见是符合规定的。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-435", "q": "“行政机关不得法外设定权力，没有法律法规依据不得作出减损公民、法人和其他组织合法权益或者增加其义务的决定”，这体现了法治政府建设中哪项要求？", "options": ["职能科学", "守法诚信", "执法严明", "权责法定"], "a": 3, "e": ".【D】“权责法定”是指权力机关的权力和责任都由法律规定，即对权力机关而言，“法不授权不可为之”。题干中“行政机关不得法外设定权力，没有法律法规依据不得……”正是体现了“法不授权不可为之”。故正确答案为D。", "tag": "法律常识"},
{"id": "law-436", "q": "根据《中华人民共和国行政诉讼法》，下列诉讼事项中，人民法院不予受理的是：", "options": ["对公安机关作出的行政拘留的决定不服", "认为行政机关违法摊派费用", "对行政机关作出的有关行政许可的决定不服", "对行政机关作出的有关工作人员奖惩的决定不服"], "a": 3, "e": ".【D】本题考查法律常识。根据《行政诉讼法》第十二条第一款规定：“人民法院受理公民、法人或者其他组织提起的下列诉讼：(一)对行政拘留、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、罚款、警告等行政处罚不服的；(二)对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的；(三)申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关作出的有关行政许可的其他决定不服的；……(九)认为行政机关违法集资、摊派费用或者违法要求履行其他义务的；……”A项正确，符合上述第（一）项的情形，人民法院应当受理。B项正确，符合上述第（九）项的情形，人民法院应当受理。C项正确，符合上述第（三）项的情形，人民法院应当受理。D项错误，根据《行政诉讼法》第十三条规定：“人民法院不受理公民、法人或者其他组织对下列事项提起的诉讼：(一)国防、外交等国家行为；(二)行政法规、规章或者行政机关制定、发布的具有普遍约束力的决定、命令；(三)行政机关对行政机关工作人员的奖惩、任免等决定；(四)法律规定由行政机关最终裁决的行政行为。”故对行政机关作出的有关工作人员奖惩的决定不服的，不能提起行政诉讼。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-437", "q": "下列选项中，属于行政行为的是。", "options": ["市场监督管理局销毁收缴的假冒伪劣产品", "城管局雇用外部人员修理其办公设备", "交警在路口安装交通标志", "财政局审批某会计师事务所的设立"], "a": 3, "e": ".【D】本题考查法律常识。A项错误，市场监督管理局查封、扣押物品或者没收非法所得等是具体行政行为，但市场监督管理局对收缴的假冒伪劣产品的销毁是行政事实行为，行政事实行为指的是行政主体基于职权实施的不能产生、变更或者消灭行政法律关系的行为。B项错误，城管局雇用外部人员修理设备，便和外部人员之间建立了承揽合同，双方是民事法律关系，城管局具有民事主体资格，未使用其行政职权，不属于行政行为。C项错误，行政行为是指行政机关行使行政权力，对特定的公民、法人和其他组织作出的有关其权利义务的单方行为。交警在路口安装交通标志是为了保障出行安全的职责行为，没有行政相对人，也没有权利义务的产生，不属于行政行为。D项正确，行政许可是指行政机关根据公民、法人或者其他组织的申请，经依法审查准予其从事特定活动的行为。《行政许可法》第十二条规定：“下列事项可以设定行政许可：……（五）企业或者其他组织的设立等，需要确定主体资格的事项；（六）法律、行政法规规定可以设定行政许可的其他事项。”财政局审批会计师事务所的设立是行政许可行为。故正确答案为D。", "tag": "法律常识"},
{"id": "law-438", "q": "下列关于公务员录用的表述，错误的是。", "options": ["新录用的公务员试用期为一年", "被依法列为失信联合惩戒对象的人员不得录用为公务员", "地方各级机关公务员的录用必要时可授权市级公务员主管部门组织", "录用公务员应当在规定的编制限额内，并有相应的职位空缺"], "a": 2, "e": ".【C】本题考查法律常识。A项正确，《公务员法》第三十四条规定：“新录用的公务员试用期为一年。试用期满合格的，予以任职；不合格的，取消录用。”B项正确，《公务员法》第二十六条规定：“下列人员不得录用为公务员：（一）因犯罪受过刑事处罚的；（二）被开除中国共产党党籍的；（三）被开除公职的；（四）被依法列为失信联合惩戒对象的；（五）有法律规定不得录用为公务员的其他情形的。”C项错误，《公务员法》第二十四条规定：“中央机关及其直属机构公务员的录用，由中央公务员主管部门负责组织。地方各级机关公务员的录用，由省级公务员主管部门负责组织，必要时省级公务员主管部门可以授权设区的市级公务员主管部门组织。”D项正确，《公务员法》第二十七条规定：“录用公务员，应当在规定的编制限额内，并有相应的职位空缺。”本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-439", "q": "1965 年，老周自建了一套房屋。2017 年，老周的房屋被划入旧城改造范围。因无产权证和土地使用证，该房屋被认定为违法建筑，城管部门依据2008 年施行的《城乡规划法》，责令老周限期拆除。对此，下列说法正确的是", "options": ["老周的房屋属于违法建筑，应当责令其自行拆除", "因旧城改造，认定老周的房屋为违法建筑已无实际意义", "城管部门适用法律错误，限期拆除的决定无效", "老周的房屋属历史遗留问题，不能得到拆迁补偿"], "a": 2, "e": ".【C】本题考查法律常识。A项错误，老周的房屋自建于1965年，在2008年《城乡规划法》颁布施行前已建成，根据法不溯及既往的原则，无法依据2008年颁布的《城乡规划法》认定老周的房屋为违法建筑。B项错误，是否认定为违法建筑，关系到老周能否获得拆迁补偿，因此，无实际意义的说法错误。C项正确，根据法不溯及既往的原则，城管部门适用法律错误，因此城管部门作出的限期拆除决定无效。D项错误，老周的房屋属于历史遗留问题，但如果根据1965年法律，老周房屋属于合法房屋的，拆迁时应当给予补偿。故正确答案为C。", "tag": "法律常识"},
{"id": "law-440", "q": "某市交警在设卡检查酒驾时，有人驾驶摩托车行驶到检查点前，突然掉头并加速逆行。对此情形，下列执勤交警的做法恰当的是", "options": ["为避免发生执法风险，放弃对该摩托车的检查", "详细记录现场执法情况，及时作出处置", "将路边的共享单车推向路面，阻止摩托车逃跑", "立即追击拦阻，防止发生酒驾事故"], "a": 1, "e": ".【B】本题考查法律常识。A项错误，在交警检查时，有人驾驶摩托车加速逆行，逃避交警的检查，该人的行为有违法的嫌疑，涉嫌酒驾或者其他违法行为，执勤交警应及时处理这种情况，放弃对摩托车的检查、让该摩托车逆行可能会造成交通事故的发生。B项正确，《道路交通安全违法行为处理程序规定》第十五条第一款规定：“公安机关交通管理部门可以利用交通技术监控设备收集、固定违法行为证据。”交警在遇到本题中的情况，应利用执法记录仪等设备详细记录现场执法情况，可以向交通管理部门反映、联合其他路口交警等，对该摩托车的车主作出处置。C项错误，将共享单车推向路面会在路面上形成障碍，影响其他车辆的通行，也会影响周围行人使用共享单车。D项错误，该摩托车车主是加速逆行，若交警及时追击，两辆车的逆行在公路上会影响其他车辆的正常出行，容易引发交通事故，造成交通混乱。故正确答案为B。", "tag": "法律常识"},
{"id": "law-441", "q": "赵某被依法列为失信联合惩戒对象。据此，有关部门可以对他采取的合法措施是", "options": ["教育管理部门禁止赵某的孩子就读重点学校", "用人单位取消赵某的年终绩效工资", "人民法院将赵某的失信情况通报其配偶所在单位", "某机关拒绝录用赵某为公务员"], "a": 3, "e": ".【D】本题考查法律。A项错误，根据《关于对失信被执行人实施联合惩戒的合作备忘录》规定：“（二十三）限制失信被执行人及失信被执行人的法定代表人、主要负责人、影响债务履行的直接责任人员、实际控制人的子女就读高收费私立学校，由最高人民法院、教育部实施。”由此可见，并不是禁止就读重点学校，而是禁止就读高收费私立学校。B项错误，根据《关于对失信被执行人实施联合惩戒的合作备忘录》规定：“（十八）禁止参评文明单位、道德模范。对于机关、企事业单位、社会团体或其领导成员为失信被执行人的，不得参加文明单位评选，已经取得文明单位荣誉称号的予以撤销。各类失信被执行人均不得参加道德模范评选，已获得道德模范荣誉称号的予以撤销。由中央宣传部、中央文明办实施。”用人单位不能因为失信原因取消失信人年终绩效工资，但可以撤销荣誉称号，取消评优评先资格。C项错误，根据《关于对失信被执行人实施联合惩戒的合作备忘录》规定：“（十五)通过‘信用中国’网站和企业信用信息公示系统向社会公布，将失信被执行人信息通过信用中国网站、企业信用信息公示系统向社会公布，由国家发展改革委、工商总局实施。（十六）通过主要新闻网站向社会公布：协调相关互联网新闻信息服务单位向社会公布失信被执行人信息，由国家网信办实施。”可见备忘录中没有规定要将信息通知配偶单位。D项正确，根据《关于对失信被执行人实施联合惩戒的合作备忘录》规定：“（十七）限制招录（聘）为公务员或事业单位工作人员。协助限制招录（聘）失信被执行人为公务员或事业单位工作人员，由中组部、人力资源社会保障部、公务员局等有关部门实施。”失信人无法报考公务员，会被限制，只有在限制消除后才能恢复正常。故正确答案为D。", "tag": "法律常识"},
{"id": "law-442", "q": "以下是某执法部门对市民网络投诉的回复情况：下列对管理员回复的评价，正确的是", "options": ["合情合理，明确表明了执法的合法依据", "内容完整，能准确告知执法信息的查询途径", "格式规范，但未具体说明执法的正当理由", "回复及时，但内容避重就轻并缺乏针对性"], "a": 3, "e": ".【D】本题考查法律。《信访条例》第二条规定：“本条例所称信访，是指公民、法人或者其他组织采用书信、电子邮件、传真、电话、走访等形式，向各级人民政府、县级以上人民政府工作部门反映情况，提出建议、意见或者投诉请求，依法由有关行政机关处理的活动。\"题目中的网络投诉，属于网上信访。根据《信访条例》第三十三条规定：“信访事项应当自受理之日起60日内办结;情况复杂的，经本行政机关负责人批准，可以适当延长办理期限，但延长期限不得超过30日，并告知信访人延期理由。”案件中，投诉时间是5月23日，处理时间是5月24日，回复及时。但回复的内容，缺乏针对性。只说了配合市政府工作，但对于老百姓提出的三个问题，为啥撕，为啥不让整改，损失谁承担并未一一作答。AB选项错误，该回复缺乏针对性，因此，内容不完整，也不够合情合理。C选项错误，回复中说明了执法的理由，即配合市政府工作。故正确答案为D。", "tag": "法律常识"},
{"id": "law-443", "q": "某局长驾驶私家车与一辆接送孩子的人力三轮车剐蹭，导致三名小学生轻微擦伤，该局长亲自将孩子们送到县医院检查治疗后，又把孩子们送到学校正常上课。事故发生时，某企业职工杨某路过并用手机录制了一段视频，视频中虽未出现该局长的画面，但在视频中插入文字“局长驾车撞上三轮车，五名孩子严重受伤，局长态度嚣张，驾车扬长而去”等严重失实信息。杨某将该视频发到朋友圈后，又被广为转发，造成了不良社会影响。对此事件，下列说法正确的是：", "options": ["杨某严重扰乱社会公共秩序，由检察机关提起公诉", "杨某不遵守社会公德，由所在企业进行处理与教育", "杨某违反治安管理处罚法，由公安机关予以相应处罚", "杨某的行为属于严重诽谤，由法院受理并判处刑罚"], "a": 2, "e": ".【C】本题考查法律。A项错误，杨某的行为造成不良社会影响，还未达到触犯刑法的程度，不属于公诉范围。B项错误，杨某行为违反了《治安管理处罚法》，应当受到行政处罚。C项正确，《治安管理处罚法》第二十五条第一项规定:“散布谣言,谎报险情、疫情、警情或者以其他方法故意扰乱公共秩序的，处五日以上十日以下拘留，可以并处五百元以下罚款。”D项错误，侮辱、诽谤罪属于告诉才处理的案件，不应由法院直接受理。故正确答案为C。", "tag": "法律常识"},
{"id": "law-444", "q": "下列最有可能不会受到治安管理处罚的是：", "options": ["两人酒后打架斗殴，但均未受伤，酒醒后双方愿意和解", "房东发现房客在租房内开赌场却不告知管理部门，反而提醒房客小心点", "小明饲养了一只属于禁养犬只的大型犬，该犬性格温和从不咬人，民警多次提醒，小明仍然坚持饲养", "在某足球比赛中，球迷不满“黑哨”，扔啤酒罐砸向裁判，但力度较轻，裁判未受伤"], "a": 0, "e": ".【A】本题考查法律常识。A项正确，根据《中华人民共和国治安管理处罚法》第九条规定：“对于因民间纠纷引起的打架斗殴或者损毁他人财物等违反治安管理行为，情节较轻的，公安机关可以调解处理。经公安机关调解，当事人达成协议的，不予处罚。经调解未达成协议或者达成协议后不履行的，公安机关应当依照本法的规定对违反治安管理行为人给予处罚，并告知当事人可以就民事争议依法向人民法院提起民事诉讼。”因此，对于两位打架斗殴后愿意和解的公民，可以不予处罚。B项错误，根据《中华人民共和国治安管理处罚法》第五十七条第二款规定：“房屋出租人明知承租人利用出租房屋进行犯罪活动，不向公安机关报告的，处二百元以上五百元以下罚款；情节严重的，处五日以下拘留，可以并处五百元以下罚款。”该房东的行为属于违反《治安管理处罚法》的行为，会受到治安管理处罚。C项错误，根据《中华人民共和国治安管理处罚法》第七十五条第一款规定：“饲养动物，干扰他人正常生活的，处警告；警告后不改正的，或者放任动物恐吓他人的，处二百元以上五百元以下罚款。”具体适用本条时，应当以他人的感受为判断标准，小明饲养了禁止饲养的大型犬，民警已多次提醒，可以看出该行为已经干扰他人的生活，因此会受到治安管理处罚。的，处警告或者二百元以下罚款；情节严重的，处五日以上十日以下拘留，可以并处五百元以下罚款：（一）强行进入性活动秩序的其他行为。因扰乱体育比赛秩序被处以拘留处罚的，可以同时责令其十二个月内不得进入体育场馆观看同类比赛；违反规定进入体育场馆的，强行带离现场。”因此，该球迷会受到治安管理处罚。故正确答案为A。", "tag": "法律常识"},
{"id": "law-445", "q": "关于政府信息公开，下列做法正确的是：", "options": ["小明因出国需要打印个人所得税缴税记录，向税务部门说明后，税务部门拒绝提供", "小张借给小吴50 万元，到期后小吴无法还款。小张想用小吴的房产抵债，向房屋管理机关提出申请查看小吴名下房", "小李因老家拆迁，想了解土地征用、拆迁补偿等方面的政策信息，但发现所在县、市网站上并没有相关信息，于是向", "小兰所在县发生洪水，省里为救灾专门提供了一笔救灾资金。救灾安置工作完成后，小兰想了解该笔资金的使用、分"], "a": 1, "e": ".【B】本题考查法律常识。A项错误，《政府信息公开条例》第二十七条规定：除行政机关主动公开的政府信息外，公民、法人或者其他组织可以向地方各级人民政府、对外以自己名义履行行政管理职能的县级以上人民政府部门申请获取相关政府信息。因此，税务部门拒绝公开说法错误。B项正确，《政府信息公开条例》第十五条规定：涉及商业秘密、个人隐私等公开会对第三方合法权益造成损害的政府信息，行政机关不得公开。C项错误，《政府信息公开条例》第二十一条规定：除本条例第二十条规定的政府信息外，设区的市级、县级人民政府及其部门还应当根据本地方的具体情况，主动公开涉及市政建设、公共服务、公益事业、土地征收、房屋征收、治安管理、社会救助等方面的政府信息；乡（镇）人民政府还应当根据本地方的具体情况，主动公开贯彻落实农业农村政策、农田水利工程建设运营、农村土地承包经营权流转、宅基地使用情况审核、土地征收、房屋征收、筹资筹劳、社会救助等方面的政府信息D项错误，《政府信息公开条例》第二十条规定：行政机关应当依照本条例第十九条的规定，主动公开本行政机关的下列政府信息：（十一）扶贫、教育、医疗、社会保障、促进就业等方面的政策、措施及其实施情况。故正确答案为B。", "tag": "法律常识"},
{"id": "law-446", "q": "据报道，某商场广告牌围挡被风吹倒，有行人被砸，送医就诊后，均无生命危险。事件发生时，市民吴某用手机录制了视频，谎称“商场牌子砸人了，3 死2 伤”。该视频被快速传播，在社会上造成不良影响。对此，下列说法正确的是", "options": ["吴某不遵守社会公德，应该由街道办进行教育与处罚", "吴某的行为违反刑法，应该由法院判处其相应的刑罚", "吴某触犯了民事法律，属于严重扰乱公共秩序的行为", "吴某违反治安管理处罚法，应接受公安机关相应处罚"], "a": 3, "e": ".【D】本题考查法律常识。《治安管理处罚法》第二十五条规定：“有下列行为之一的，处五日以上十日以下拘留，可以并处五百元以下罚款；情节较轻的，处五日以下拘留或者五百元以下罚款:（一）散布谣言，谎报险情、疫情、警情或者以其他方法故意扰乱公共秩序的；（二）投放虚假的爆炸性、毒害性、放射性、腐蚀性物质或者传染病病原体等危险物质扰乱公共秩序的；（三）扬言实施放火、爆炸、投放危险物质扰乱公共秩序的。”A项错误，吴某在网上传播虚假信息，散布谣言，不仅仅是不遵守社会公德的行为，是违法行为。B项错误，吴某的行为虽然在社会上造成了不良影响，但是并不是对社会具有很大的危害，没有触犯刑法规定，是一般违法行为，非犯罪行为。C项错误，民法调整平等主体的自然人、法人和非法人组织之间的人身关系和财产关系。吴某的行为并不涉及到民事法律关系，触犯的不是民事法律。D项正确，吴某在网上制造虚假信息，散布谣言，在社会上造成了不良的影响，是违反治安管理的行为，违反了治安管理处罚法，应该由公安机关进行相应的处罚。故正确答案为D。", "tag": "法律常识"},
{"id": "law-447", "q": "某市一公民从海外回国，入境时带回的一箱化妆品被该市海关扣押，该公民不服，其申请行政复议的机关应该是", "options": ["该市海关", "该市人民政府", "该市海关的上一级海关", "该市所属省级人民政府"], "a": 2, "e": ".【C】本题考查法律常识。《行政复议法》第十二条规定：“对县级以上地方各级人民政府工作部门的具体行政行为不服的，由申请人选择，可以向该部门的本级人民政府申请行政复议，也可以向上一级主管部门申请行政复议。对海关、金融、国税、外汇管理等实行垂直领导的行政机关和国家安全机关的具体行政行为不服的，向上一级主管部门申请行政复议。”该公民对市海关的行政行为不服，应向该市海关的上一级海关申请行政复议，C项正确，ABD项错误。故正确答案为C。", "tag": "法律常识"},
{"id": "law-448", "q": "王某向县规划部门申请旧房改建，获得批准。张某认为王某的改建严重影响了其通行和采光，遂以阻挡消防通道为由向县消防部门举报。消防部门调查后，责令王某停止施工，并限期拆除已建部分。下列关于本案的说法，不正确的是", "options": ["规划部门有权要求消防部门撤销处罚决定", "张某有权向规划部门申请撤销改建许可", "消防部门可以请求县政府撤销改建许可", "改建许可被撤销前应中止处罚决定的执行"], "a": 0, "e": ".【A】本题考查法律常识。A项错误，可撤销的具体行政行为必须经过法定程序由国家有权机关作出撤销决定，才能否定其法律效力。法定程序是指行政复议、行政诉讼和行政监督程序。行政相对人可以通过复议和诉讼途径，由复议机关和法院撤销该行政行为，行政监督程序中，上级主管部门有权撤销该具体行政行为，机关发现行政行为有可撤销情形的，也能撤销该具体行政行为。因此，本题中，规划局和消防部门属于平级单位，无权要求消防部门撤销处罚决定。B、C项正确，《行政许可法》第七条规定：“公民、法人或者其他组织对行政机关实施行政许可，享有陈述权、申辩权；有权依法申请行政复议或者提起行政诉讼；其合法权益因行政机关违法实施行政许可受到损害的，有权依法要求赔偿。”《行政许可法》第六十九条规定：“有下列情形之一的，作出行政许可决定的行政机关或者其上级行政机关，根据利害关系人的请求或者依据职权，可以撤销行政许可：（一）行政机关工作人员滥用职权、玩忽职守作出准予行政许可决定的；（二）超越法定职权作出准予行政许可决定的；（三）违反法定程序作出准予行政许可决定的；（四）对不具备申请资格或者不符合法定条件的申请人准予行政许可的；（五）依法可以撤销行政许可的其他情形。”张某作为利害关系人，有权向规划部门申请撤销改建许可。消防部门可以请求县规划部门的上级机关（县政府）撤销改建许可。D项正确，信赖保护原则是行政法的一项重要原则，指的是行政行为作出后,行政相对人基于对行政行为的信赖，而做出的行为是受到保护的，行政机关不得擅自撤销、变更已生效的行政行为。本题中，王某改建房屋是获得了规划部门批准的，改建许可不得随意撤销。如果此时继续进行处罚执行，拆除王某已建房屋，会对王某利益造成重大损害。因此，改建许可被最终撤销前，处罚中止执行。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-449", "q": "张某驾车时因未张贴“交强险”标识，被交警孔某拦下，当场作出罚款50 元的决定。下列关于该行政处罚的说法，正确的是", "options": ["孔某一人不能当场作出这一处罚决定", "张某在处罚决定作出前有权要求听证", "孔某须将处罚决定报所属交警大队备案", "张某若不服处罚，起诉前应先提请复议"], "a": 2, "e": ".【C】本题考查法律常识。A项错误，根据《行政处罚法》第三十三条的规定：“违法事实确凿并有法定依据，对公民处以五十元以下、对法人或者其他组织处以一千元以下罚款或者警告的行政处罚的，可以当场作出行政处罚决定。当事人应当依照本法第四十六条、第四十七条、第四十八条的规定履行行政处罚决定。”交警孔某对张某处以50元的罚款，符合行政处罚简易程序的条件，该行政处罚决定是可以一人当场作出的。B项错误，根据《行政处罚法》第四十二条第一款规定：“行政机关作出责令停产停业、吊销许可证或者执照、较大数额罚款等行政处罚决定之前，应当告知当事人有要求举行听证的权利；当事人要求听证的，行政机关应当组织听证。当事人不承担行政机关组织听证的费用。”并不是所有的行政处罚种类都可以要求听证，对张某作出的50元的行政处罚决定，张某是不能要求听证的。C项正确，根据《行政处罚法》第三十四条第三款的规定：“执法人员当场作出的行政处罚决定，必须报所属行政机关备案。”孔某需要将其作出的行政处罚决定报其所属的交警大队备案。D项错误，根据《行政处罚法》第三十五条的规定：“当事人对当场作出的行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。”所以，张某若不服行政处罚，可以申请行政诉讼或者行政复议，没有行政复议前置的强制性规定。故正确答案为C。", "tag": "法律常识"},
{"id": "law-450", "q": "公务员王某准备辞去公职，下列说法中错误的是", "options": ["王某辞去公职后，不再具有公务员身份", "王某辞去公职的申请，应交由任免机关审批", "王某辞去公职后，可以自由选择企业或社会组织任职", "王某离职前，应当办理公务交接手续"], "a": 2, "e": ".【C】本题考查法律常识。A项正确，根据《公务员法》第二条规定，本法所称公务员，是指依法履行公职、纳入国家行政编制、由国家财政负担工资福利的工作人员。可知王某辞去公职后，即与公务员身份定义不符，故不再具有公务员身份。B项正确，根据《公务员法》第八十条规定，公务员辞去公职，应当向任免机关提出书面申请。任免机关应当自接到申请之日起三十日内予以审批，其中对领导成员辞去公职的申请，应当自接到申请之日起九十日内予以审批。C项错误，根据《公务员法》第一百零二条第一款规定，公务员辞去公职或者退休的，原系领导成员的公务员在离职三年内，其他公务员在离职两年内，不得到与原工作业务直接相关的企业或者其他营利性组织任职，不得从事与原工作业务直接相关的营利性活动。由此可知，王某辞去公职后的任职是受到限制的，并非可以自由选择。D项正确，根据《公务员法》第八十六条规定，公务员辞职或者被辞退，离职前应当办理公务交接手续，必要时按照规定接受审计。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-451", "q": "下列行政行为属于行政处罚的是：", "options": ["质监部门将甲生产的涉嫌违法使用添加剂的香肠予以先行登记保存", "土地管理部门对于乙、丙之间宅基地权属纠纷作出裁处", "卫生部门对感染传染病病毒的患者丁进行强制隔离", "消防部门对未经消防安全检查擅自营业的戊茶楼作出责令停产停业的决定"], "a": 3, "e": ".【D】本题考查行政处罚的相关知识，根据《中华人民共和国行政处罚法》第八条的规定：“行政处罚的种类:（一）警告；（二）罚款；（三）没收违法所得、没收非法财物；（四）责令停产停业；（五）暂扣或者吊销许可证、暂扣或者吊销执照；（六）行政拘留；（七）法律、行政法规规定的其他行政处罚。”A项错误，质监部门将甲生产的涉嫌违法使用添加剂的香肠予以先行登记保存属于行政强制。行政强制是指行政机关为了实现行政目的，依据法定职权和程序做出的对相对人的人身、财产和行为采取的强制性措施。这种做法的目的是以防证据丢失或者以后难以再获得涉嫌违法使用添加剂的香肠。因此，质监部门将甲生产的涉嫌违法使用添加剂的香肠予以先行登记保存属于行政强制。B项错误，土地管理部门对乙、丙之间宅基地权属纠纷作出裁处属于行政裁决。行政裁决是指行政机关或法定授权的组织，依照法律授权，对当事人之间发生的、与行政管理活动密切相关的、与合同无关的民事纠纷进行审查，并作出裁决的具体行政行为。C项错误，卫生部门对感染传染病病毒的患者丁进行强制隔离属于行政强制。行政强制是指行政机关为了实现行政目的，依据法定职权和程序做出的对相对人的人身、财产和行为采取的强制性措施。因此，卫生部门为了避免传染病病毒的传播，对患者进行隔离属于行政强制。D项正确，根据《中华人民共和国行政处罚法》第八条的规定：行政处罚的种类:（一）警告；（二）罚款；（三）没收违法所得、没收非法财物；（四）责令停产停业；（五）暂扣或者吊销许可证、暂扣或者吊销执照；（六）行政拘留；（七）法律、行政法规规定的其他行政处罚。因此，消防部门对未经消防安全检查擅自营业的戊茶楼作出责令停产停业的决定，属于行政处罚。故正确答案为D。", "tag": "法律常识"},
{"id": "law-452", "q": "行政行为应依法实施，遵守法定权限、法定条件、法定要求和法定程序。行政法规、行政规章和行政规定均不得与法律相抵触，不得规定依法只能由法律规定的事项。这是行政程序法的（）。", "options": ["正当程序原则", "依法行政原则", "公开原则", "参与原则"], "a": 1, "e": ".【B】本题考查法律常识，主要涉及行政法的基本原则。A项错误，正当程序原则是当代行政法的主要原则之一。它包括以下几个原则：第一，行政公开原则，是指除涉及国家秘密和依法受到保护的商业秘密、个人隐私外，行政机关实施行政管理应当公开，以实现公民的知情权。第二，公众参与原则，是指行政机关做出重要规定或者决定，应当听取公民、法人和其他组织的意见，特别是作出对公民、法人和其他组织不利的决定，要听取他们的陈述和申辩。第三，回避原则，行政机关工作人员履行职责，与行政管理相对人存在利害关系时，应当回避。题干表述与程序正当无关，A不应选。B项正确，依法行政原则是行政法的首要原则，它的要求包括两个方面：第一，行政机关必须遵守现行有效的法律。这一方面的基本要求是：行政机关实施行政管理，应当依照法律、法规、规章的规定进行，禁止行政机关违反现行有效的立法性规定。第二，行政机关应当依照法律授权活动。这一方面的基本要求是：没有法律、法规、规章的规定，行政机关不得作出影响公民、法人或者其他组织合法权益或者增加公民、法人和其他组织义务的决定。C、D项错误，公开原则和参与原则属于程序正当原则的要求，与题干表述无关，不应选。故正确答案为B。", "tag": "法律常识"},
{"id": "law-453", "q": "以下情形，向人民法院提起行政诉讼，法院不予受理的是（）。", "options": ["对行政拘留、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、罚款、警告等行政处罚不", "对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的", "认为行政机关侵犯其自主权或者农村土地承包经营权、农村土地经营权的", "行政机关对其工作人员的奖惩、任免等决定，工作人员认为不合理，要求撤销的"], "a": 3, "e": "", "tag": "法律常识"},
{"id": "law-454", "q": "为改善甲村的交通，乡政府决定对甲村村民每人征收300 元，在向县政府报备后，委托甲村村委会收取。村会计张某上门向李某收取了该费用，李某不服，提起行政诉讼。本案的被告应是（）", "options": ["县政府", "甲村村委会", "乡政府", "县政府、乡政府是共同被告"], "a": 2, "e": "识【C】本题考查法律常识，主要考查《行政诉讼法》的相关知识点。《行政诉讼法》第二十六条第一款规定：“公民、法人或者其他组织直接向人民法院提起诉讼的，作出行政行为的行政机关是被告。”A项错误，根据《行政诉讼法》第二十六条第一款规定，县政府没有作出该行政行为，所以不是诉讼主体。组织，实行民主选举、民主决策、民主管理、民主监督。”所以甲村村委会不是行政机关，也不是行政诉讼主体。C项正确，根据《行政诉讼法》第二十六条第一款规定，乡政府作出行政征收决定，行政诉讼的被告是行政主体，所以诉讼主体是乡政府。D项错误，根据《行政诉讼法》第二十六条第四款规定：“两个以上行政机关作出同一行政行为的，共同作出行政行为的行政机关是共同被告。”县政府没有作出该行政行为，不是诉讼主体，故县政府、乡政府是共同被告说法错误。故正确答案为C。", "tag": "法律常识"},
{"id": "law-455", "q": "在行政主体制度中，下列关于法律法规授权组织的说法不正确的是。", "options": ["该组织应当是国家机关以外的组织", "基于授权，该组织具有了国家机关资格", "该组织能独立行使法律法规授予的特定行政职权", "该组织对行使法律法规授权的行为独立承担责任"], "a": 1, "e": ".【B】本题考查法律常识，主要涉及行政法中法律法规授权组织的相关知识点。A项正确，法律、法规授权组织是指根据法律法规的规定，可以以自己的名义从事行政管理活动、参加行政复议和行政诉讼并承担相应法律责任的非国家机关组织。B项错误，基于授权，法律、法规授权组织可以行使特定的行政职权，但并不意味着其获得了国家机关资格。C项正确，法律、法规授权组织行使的是特定行政职权，而不是一般行政职权。一般行政职权是指行政机关根据宪法、各种组织法而获得的行政职权，特定行政职权是指单行法律、法规基于处理特定行政事务的需要而规定的行政职权。D项正确，法律、法规授权的组织可以以自己名义行使法律法规授权的行为，并由其本身对外承担法律责任。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-456", "q": "下列关于行政许可的表述中，错误的是", "options": ["实施行政许可，应当遵循便民的原则，提高办事效率，提供优质服务", "公民、法人或者其他组织依法取得的行政许可受法律保护，行政机关不得擅自改变已经生效的行政许可", "行政许可的实施和结果，除涉及国家秘密的外，应当公开", "公民、法人或者其他组织对行政机关实施行政许可，享有陈述权、申辩权"], "a": 2, "e": ".【C】本题主要考查行政许可法有关内容。A项正确，《中华人民共和国行政许可法》第六条规定：实施行政许可，应当遵循便民的原则，提高办事效率，提供优质服务。B项正确，《中华人民共和国行政许可法》第八条规定：公民、法人或者其他组织依法取得的行政许可受法律保护，行政机关不得擅自改变已经生效的行政许可。C项错误，《中华人民共和国行政许可法》第五条第二款规定：行政许可的实施和结果，除涉及国家秘密、商业秘密或者个人隐私外，应当公开。选项中只提到国家秘密，说法不准确，表述错误。D项正确，《中华人民共和国行政许可法》第七条规定：公民、法人或者其他组织对行政机关实施行政许可，享有陈述权、申辩权，有权依法申请行政复议或者提起行政诉讼，其合法权益因行政机关违法实施行政许可受到损害的，有权依法要求赔偿。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-457", "q": "行政许可是指行政机关根据行政相对人的申请，经依法审查，准予其从事特定活动的行为。关于行政许可，下列说法中错误的是：", "options": ["行政许可主要是指法定的行政审批", "“非行政许可审批事项”这一类型将会不复存在", "税务机关对企业申请享受纳税减免优惠的审批属于行政许可", "行政许可不应包括市场竞争机制能够有效调节的事项"], "a": 2, "e": ".【C】本题考查行政法，主要涉及行政许可的相关知识。A项正确，根据《中华人民共和国行政许可法》第二条，本法所称行政许可，是指行政机关根据公民、法人或者其他组织的申请，经依法审查，准予其从事特定活动的行为。所以行政许可主要是指法定的行政审批。B项正确，2015年5月14日，国务院发布《关于取消非行政许可审批事项的决定》，在前期大幅减少部门非行政许可审批事项的基础上，再取消49项非行政许可审批事项，将84项非行政许可审批事项调整为政府内部审批事项。今后不再保留“非行政许可审批”这一审批类别。所以“非行政许可审批事项”这一类型将会不复存在。C项错误，根据国家税务总局《关于税务行政许可若干问题的公告》（2016年第11号公告）指出，税务行政许可事项有：（一）企业印制发票审批；（二）对纳税人延期缴纳税款的核准；（三）对纳税人延期申报的核准；（四）对纳税人变更纳税定额的核准；（五）增值税专用发票（增值税税控系统）最高开票限额审批；（六）对采取实际利润额预缴以外的其他企业所得税预缴方式的核定；（七）非居民企业选择由其主要机构场所汇总缴纳企业所得税的审批。“税务机关对企业申请享受纳税减免优惠的审批”不属于上述税务机关的行政许可事项。D项正确，《国务院关于第六批取消和调整行政审批项目的决定》（国发〔2012〕52号）指出：凡公民、法人或者其他组织能够自主决定，市场竞争机制能够有效调节，行业组织或者中介机构能够自律管理的事项，政府都要退出。由此可见行政许可不应包括市场竞争机制能够有效调节的事项。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-458", "q": "以下行为属于行政诉讼受理范围的是：", "options": ["行政机关对其工作人员的奖惩决定", "行政机关对其工作人员的任免决定", "行政机关对其工作人员的离退休决定", "行政机关吊销其工作人员参股企业的营业执照"], "a": 3, "e": ".【D】本题考查法律常识。A、B项错误，《行政诉讼法》第十三条规定：“人民法院不受理公民、法人或者其他组织对下列事项提起的诉讼：（三）行政机关对行政机关工作人员的奖惩、任免等决定。”C项错误，行政机关对其工作人员的离退休决定属于内部行政行为，不是具体行政行为，所以不属于人民法院行政诉讼的受案范围。D项正确，根据《行政诉讼法》第十二条规定：人民法院受理公民、法人和其它组织对拘留、罚款、吊销许可证和执照、责令停产停业、没收财物等行政处罚不服的提起的诉讼。因此，依此若对此行政处罚提起诉讼，法院应予受理。该项中，行政机关吊销其工作人员参股企业的营业执照，属于具体行政行为，属于行政诉讼受理范围。故正确答案为D。", "tag": "法律常识"},
{"id": "law-459", "q": "赵某以要债为名驾车堵住甲公司的大门，致使甲公司车辆无法进出。辖区派出所派警察孙某前去处理。孙某以扰乱企业生产秩序为由，对赵某处以150 元的罚款。下列关于该行政处罚的说法，错误的是：", "options": ["该处罚决定书可以当场制作并交付赵某", "该处罚决定书应按预定格式书写", "该处罚决定书必须加盖公安机关印章", "该处罚决定书必须报公安机关备案"], "a": 2, "e": ".【C】本题考查行政法。A项，题目中给出的行为是扰乱企业生产秩序，这一行为实际上是违反治安管理的行为，根据《治安管理处罚法》规定：“违反治安管理行为事实清楚，证据确凿，处警告或者二百元以下罚款的，可以当场作出治安管理处罚决定。”因此，对孙某处以150元罚款可以适用简易程序，A项是正确的。B、D项，根据《治安管理处罚法》第一百零一条规定：“当场作出治安管理处罚决定的，人民警察应当向违反治安管理行为人出示工作证件，并填写处罚决定书。处罚决定书应当当场交付被处罚人；有被侵害人的，并将决定书副本抄送被侵害人。前款规定的处罚决定书，应当载明被处罚人的姓名、违法行为、处罚依据、罚款数额、时间、地点以及公安机关名称，并由经办的人民警察签名或者盖章。”当场作出治安管理处罚决定的，经办的人民警察应当在二十四小时内报所属公安机关备案。所以B项处罚决定书应按预定格式书写及D项处罚决定书必须报公安机关备案的表述正确。C项，依据《治安管理处罚法》第一百零一条第二款规定：“由经办的人民警察签名或者盖章就可以，不是必须加盖公安机关印章。当场作出治安管理处罚决定的，经办的人民警察应当在二十四小时内报所属公安机关备案即可。”C项表述错误。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-460", "q": "某县新建公路路口设置了超速违章摄像头，赵某不知情，多次超速驾车在该路段被拍照，且未收到违章通知。赵某被处罚后不服，将县公安局告上法庭。恰逢县公安局聘请了某专职律师作为法律顾问。下列做法符合我国《行政诉讼法》规定的是：", "options": ["该律师可全权代理县公安局出庭应诉，县公安局不必再派员出庭", "为查明案件事实的需要，该律师可自行向赵某调取相关证据", "该律师查阅、复制该案庭审材料必须经人民法院许可", "若赵某和县公安局同意，则人民法院可适用简易程序审理该案"], "a": 3, "e": ".【D】A项错误，《行政诉讼法》第三条第三款规定：“被诉行政机关负责人应当出庭应诉。不能出庭的，应当委托行政机关相应的工作人员出庭。”B项错误，《行政诉讼法》第三十五条规定：“在诉讼过程中，被告及其诉讼代理人不得自行向原告、第三人和证人收集证据。”C项错误，《行政诉讼法》第三十二条规定：“代理诉讼的律师，有权按照规定查阅、复制本案有关材料，有权向有关组织和公民调查，收集与本案有关的证据。”故代理律师有权查阅、复制案件相关庭审材料，无需经人民法院许可。D项正确，《行政诉讼法》第八十二条规定：“人民法院审理下列第一审行政案件，认为事实清楚、权利义务关系明确、争议不大的，可以适用简易程序：（一）被诉行政行为是依法当场作出的；（二）案件涉及款额二千元以下的；（三）属于政府信息公开案件的。除前款规定以外的第一审行政案件，当事人各方同意适用简易程序的，可以适用简易程序。发回重审、按照审判监督程序再审的案件不适用简易程序。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-461", "q": "某公司非法占用公路堆放建筑材料，交通主管部门对其做出了行政处罚。在作出行政处罚前，交通主管部门向该公司告知了作出处罚决定的事实、理由及依据，并告知了该公司依法享有的权利。这一做法体现的行政法基本原则是：", "options": ["合法行政原则", "合理行政原则", "高效便民原则", "程序正当原则"], "a": 3, "e": ".【D】本题考查行政法的有关知识。行政法的基本原则是指导和规范行政法的立法、执法以及指导规范行政行为的实施和行政争议处理的基础性法则。A项错误：合法行政原则体现在行政机关必须遵守现行有效的法律，行政机关应当依照法律授权活动。本题没有体现这一原则；B项错误：合理行政原则指行政决定应当具有一个有正常理智的普通人所能达到的合理与适当。本题没有体现这一原则；C项错误：高效便民原则要求行政机关要积极履行法定职责，禁止不作为或者不完全作为；遵守法定时限，禁止超越法定时限或者不合理延迟；不得增加当事人的程序负担。本题没有体现这一原则；D项正确：程序正当原则要求执法人员要严格遵循法定程序，依法保障行政管理相对人、利害关系人的知情权、参与权和救济权。本题中交通主管部门严格依照法律程序对违法公司进行行政处罚，并告知其依法享有的权利，完全符合程序正当原则的要求。故正确答案为D。", "tag": "法律常识"},
{"id": "law-462", "q": "村民王某提出宅基地使用申请，乡政府审核后报县土地主管部门审批，获得批准。县水利主管部门巡查时发现王某的房屋建在泄洪区，便责令王某停止建设，并自行拆除已建部分。王某不服水利部门的处罚。下列关于本案的说法，正确的是：", "options": ["法院应将乡政府列为共同被告", "法院应将县土地主管部门列为第三人", "法院应判决县土地部门赔偿王某的损失", "法院应告知王某先复议，不服后方可起诉"], "a": 1, "e": ".【B】土地主管部门与王某受处罚的具体行政行为有利害关系，如果土地主管部门的批准行为合法，那么王某就会胜诉，被诉具体行政行为就会被撤销；如果土地主管部门批准行为违法，王某将会败诉，被诉具体行政行为就会维持，王某因受处罚所遭受的损失将应由县土地主管部门予以承担。因此，土地主管部门的审批行为是否合法，应当由土地主管部门在诉讼中进行举证或辩论，这样才能有利于查明案情，因此可以作为第三人参加诉讼。故B项正确。故正确答案为B。", "tag": "法律常识"},
{"id": "law-463", "q": "甲市新华区人民政府决定将其管理的国有电缆厂出售，该厂的承包人张某以侵犯其经营自主权为由提出行政复议。张某可以提请行政复议的机关是：", "options": ["甲市人民政府", "甲市新华区国资委", "甲市新华区人民政府", "甲市国资委"], "a": 0, "e": ".【A】行政复议是指公民、法人或者其他组织认为行政主体的具体行政行为违法或不当侵犯其合法权益，依法向主管行政机关提出复查该具体行政行为的申请，行政复议机关依照法定程序对被申请的具体行政行为进行合法性、适当性审查，并作出行政复议决定的一种法律制度。一级复议制度是中国《行政复议法》确立的基本制度。一级复议制度是指公民、法人或者其他组织对行政机关作出的具体行政行为不服，可以向该行政机关的上一级行政机关或者法律、法规规定的其他机关申请复议，对复议决定不服，只能依法向人民法院提起行政诉讼，不得再向复议机关的上一级行政机关申请复议的制度。甲市新华区人民政府的上一级行政机关是甲市人民政府，因此，应当向甲市市政府申请复议。故正确答案为A。", "tag": "法律常识"},
{"id": "law-464", "q": "行政法是调整行政活动的法律规范的总称，分为一般行政法和特别行政法两个部分。下列法律属于一般行政法的是：", "options": ["《国防法》", "《预算法》", "《国家安全法》", "《公务员法》"], "a": 3, "e": ".【D】一般行政法又称为普通行政法，是指适用于所有（或者大多数）行政机关行政活动领域的行政法规范，主要包括行政组织法、行政行为法和行政救济法。比如《公务员法》《行政处罚法》《行政复议法》等。而特别行政法是指规范某一特定行政领域的行政法，如《治安管理处罚法》《海关法》《教育法》等。题干中《国防法》《预算法》《国家安全法》都是针对某一特定领域而适用的法，《公务员法》适用于所有公务员的管理，属于一般行政法。故正确答案为D。", "tag": "法律常识"},
{"id": "law-465", "q": "下列关于国家行政机关之间的说法正确的是：", "options": ["各级国家行政机关都有权实施行政处罚", "行政诉讼实行举证责任倒置原则，因此，行政机关承担全部举证责任", "国家行政机关公务员被判处刑罚的，给予开除处分", "国务院的法定会议形式分为国务院常务会议、国务院全体会议、国务院办公会议"], "a": 2, "e": ".【C】A项错误，根据我国《行政处罚法》的规定，只有享有法定权限的法定机关或经过法律、法规授权的组织才可以实施行政处罚；B项错误，行政诉讼中的举证责任倒置是指在通常情况下由行政机关承担举证责任，但并不代表原告人不承担任何举证责任；D项错误，国务院法定会议只包括常务会议和全体会议，不包括办公会议。故正确答案为C。", "tag": "法律常识"},
{"id": "law-466", "q": "行政处罚是指行政机关依法对违反行政管理秩序的公民、法人或其他组织给予制裁的行政行为。据此，下列属于“行政处罚”的是：", "options": ["暂扣违章司机的机动车驾驶证", "对醉酒的人约束至酒醒", "对严重违反《公务员法》的公务员给予开除处分", "对到期不缴纳税款的纳税人，按日加收滞纳税款万分之五的滞纳金"], "a": 0, "e": ".【A】判别是否属于行政处罚，最重要的是看有关行为是否违犯了《行政处罚法》的相关规定。A项的行为属于《行政处罚法》的范畴；B项《新治安管理处罚法》对醉酒的人约束至酒醒属于行政强制措施；C项对严重违反《公务员法》的公务员给予开除处分属于行政处分；D项对到期不缴纳税款的纳税人，按日加收滞纳税款万分之五的滞纳金是《中华人民共和国税收征收管理法》所规定的，不属于行政处罚范畴。故正确答案为A。本题相关知识点：《行政处罚法》第八条规定了行政处罚的种类，包括：（一）警告；（二）罚款；（三）没收违法所得、没收非法财物；（四）责令停产停业；（五）暂扣或者吊销许可证、暂扣或者吊销执照；（六）行政拘留；（七）法律、行政法规规定的其他行政处罚。注意：法律可以设定各种行政处罚。限制人身自由的行政处罚，只能由法律设定。", "tag": "法律常识"},
{"id": "law-467", "q": "卫生部和国家工商行政管理总局对某国有企业共同作出一项行政处罚，该企业不服欲申请行政复议，应当如何处理：", "options": ["该企业应当向国务院申请行政复议，由国务院作出行政复议决定", "该企业可以同时向两个机构申请行政复议，由国务院作出行政复议决定", "该企业可以同时向这两个机构申请行政复议，由作出具体行政行为的国务院机构共同作出行政复议决定", "该企业可以向其中任何一个机构申请行政复议，由作出具体行政行为的国务院机构共同作出行政复议决定"], "a": 3, "e": ".【D】《行政复议法实施条例》第二十三条规定：“申请人对两个以上国务院部门共同作出的具体行政行为不服的，依照行政复议法第十四条的规定，可以向其中任何一个国务院部门提出行政复议申请，由作出具体行政行为的国务院部门共同作出行政复议决定。”故正确答案为D。本题相关知识点：行政复议，是指公民、法人或者其他组织不服行政主体作出的具体行政行为，认为行政主体的具体行政行为侵犯了其合法权益，依法向法定的行政复议机关提出复议申请，行政复议机关依法对该具体行政行为进行合法性、合理性审查，并作出行政复议决定的行政行为。是公民、法人或其他组织通过行政救济途径解决行政争议的一种方法。", "tag": "法律常识"},
{"id": "law-468", "q": "小王参加公务员录用考试被某机关录用，在试用期内因违反公务员纪律被取消录用，小王不服，他可以采取的正确做法是：", "options": ["向人民政府申请行政复议", "向人民法院提起行政诉讼", "向公务员主管部门提出申诉", "向人事争议仲裁委员会申请仲裁"], "a": 2, "e": ".【C】新《公务员法》第九十五条第一款规定：“公务员对涉及本人的下列人事处理不服的，可以自知道该人事处理之日起三十日内向原处理机关申请复核；对复核结果不服的，可以自接到复核决定之日起十五日内，按照规定向同级公务员主管部门或者作出该人事处理的机关的上一级机关提出申诉；也可以不经复核，自知道该人事处理之日起三十日内直接提出申诉：（一）处分；（二）辞退或者取消录用；（三）降职；（四）定期考核定为不称职；（五）免职；（六）申请辞职、提前退休未予批准；（七）不按照规定确定或者扣减工资、福利、保险待遇；（八）法律、法规规定可以申诉的其他情形。”因此，ABD项不符合题意。故正确答案为C。", "tag": "法律常识"},
{"id": "law-469", "q": "关于行政处罚，下列哪个选项是正确的？", "options": ["法律法规可以设定各种行政处罚，但限制人身自由的行政处罚，只能由法律设定", "对于依法给予五十元以下罚款的行政处罚决定，行政机关可以当场收缴罚款", "对于吊销营业执照的行政处罚，行政机关在作出决定之前应当告知当事人有要求举行听证的权利", "行政处罚由具有行政处罚权的行政机关在法定授权范围内实施"], "a": 2, "e": ".【C】本题考查行政法常识。A项错误，《中华人民共和国行政处罚法》第九条规定：“法律可以设定各种行政处罚。限制人身自由的行政处罚，只能由法律设定。”法规并不能设定各种行政处罚。B项错误，《中华人民共和国行政处罚法》第四十六条第一款规定：“作出罚款决定的行政机关应当与收缴罚款的机构分离。”行政机关一般不能当场收缴罚款。C项正确，《中华人民共和国行政处罚法》第四十二条第一款规定：“行政机关作出责令停产停业、吊销许可证或者执照、较大数额罚款等行政处罚决定之前，应当告知当事人有要求举行听证的权利；当事人要求听证的，行政机关应当组织听证。”D项错误，《中华人民共和国行政处罚法》第十五条规定：“行政处罚由具有行政处罚权的行政机关在法定职权范围内实施。”“法定职权”和“法定授权”不是同一概念。故正确答案为C。", "tag": "法律常识"},
{"id": "law-470", "q": "《中华人民共和国行政诉讼法》规定，公民、法人或者其他组织认为行政机关和行政机关工作人员的行政行为侵犯其合法权益，有权向人民法院提起行政诉讼。以下提起的诉讼中不属于行政诉讼受案范围的是：", "options": ["甲公民对乙公安机关对其作出的行政拘留决定不服", "乙公民对丙市政府制定、发布的地方政府规章不服", "丙公司对丁行政机关侵犯其经营自主权的行为不服", "丁公司对戊行政机关滥用行政权力排除或限制竞争的行为不服"], "a": 1, "e": ".【B】本题考查法律常识。A项正确，《行政诉讼法》第十二条规定：“人民法院受理公民、法人或者其他组织提起的下列诉讼：（一）对行政拘留、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、罚款、警告等行政处罚不服的。”B项错误，丙市政府制定、发布的地方政府规章不属于行政诉讼法规定的行政诉讼受案范围，故选项错误。C项正确，《行政诉讼法》第十二条规定：“人民法院受理公民、法人或者其他组织提起的下列诉讼：（七）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权的。”D项正确，《行政诉讼法》第十二条规定：“人民法院受理公民、法人或者其他组织提起的下列诉讼：（八）认为行政机关滥用行政权力排除或者限制竞争的。”本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-471", "q": "私家车主陈某违章停车，为逃避罚单，卸走车牌，不料车被交警拖走。为应付交警拖车，陈某到派出所报警称车牌被盗。对此，正确的处理是：", "options": ["只需要对陈某违章停车给予交通行政处罚", "只需要对陈某假报警的行为给予治安行政处罚", "对陈某违章停车和假报警行为，择一重者处罚", "对陈某违章停车和假报警行为，都要进行处罚"], "a": 3, "e": ".【D】本题考查法律常识。题目中陈某共有违章停车、不按规定安装车牌号、假报警等三种违法行为。①违章停车。根据《中华人民共和国道路交通安全法》第九十三条规定：“对违反道路交通安全法律、法规关于机动车停放、临时停车规定的，可以指出违法行为，并予以口头警告，令其立即驶离。机动车驾驶人不在现场或者虽在现场但拒绝立即驶离，妨碍其他车辆、行人通行的，处二十元以上二百元以下罚款，并可以将该机动车拖移至不妨碍交通的地点或者公安机关交通管理部门指定的地点停放”②不按规定安装车牌号。根据《中华人民共和国道路交通安全法》第九十五条第二款规定：“故意遮挡、污损或者不按规定安装机动车号牌的，依照本法第九十条的规定予以处罚。”③假报警。假报警行为扰乱了公安机关的正常工作秩序，根据《中华人民共和国治安管理处罚法》第二十三条规定：“有下列行为之一的，处警告或者二百元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处五百元以下罚款：(一)扰乱机关、团体、企业、事业单位秩序，致使工作、生产、营业、医疗、教学、科研不能正常进行，尚未造成严重损失的”题目中陈某有三种不同的违法行为，不符合“一事不再罚”原则，应对三种违法行为分别予以处罚。比较选项，ABC均是对一种违法行为处罚，明显错误；D项虽不全面，但相对其他选项，可以作为正确答案。故正确答案为D。", "tag": "法律常识"},
{"id": "law-472", "q": "对于深圳市用人单位新招聘的聘任制公务员，下列情形中，除（）外，用人机关不得约定试用期。", "options": ["委任制公务员转为聘任制公务员的", "军队转业干部安置为聘任制公务员的", "聘任制公务员转任的", "曾任本市行政机关领导职务公务员的"], "a": 3, "e": ".【D】本题考查行政法的相关规定。根据《深圳市行政机关聘任制公务员管理办法》第三十条规定：对调任、转任、军队转业干部安置为聘任制公务员或委任制公务员转为聘任制公务员的，用人机关不得约定试用期。据此，A、B、C项均属于用人机关不得约定试用期的情形，D项不属于此情形。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-473", "q": "深圳市行政执法类公务员转任本市其他职类职务的，转任后任职时间（），工资按照新任职务确定。", "options": ["自任行政执法类公务员之日起计算", "自任行政执法类公务员见习期满之日起计算", "重新计算", "视具体情况确定计算方式"], "a": 2, "e": ".【C】本题考查行政法相关规定。根据《深圳市行政机关行政执法类公务员管理办法》第三十六条规定，行政执法类公务员转任本市其他职类职务的，应当具备本科以上学历，且在行政执法职位工作满2年（含试用期）。转任后任职时间重新计算，工资按照新任职务确定。据此A、B、D项错误，C项正确。故正确答案为C。", "tag": "法律常识"},
{"id": "law-474", "q": "某公安派出所工作人员张某违法采取了限制公民刘某人身自由的行政强制措施。根据《中华人民共和国国家赔偿法》的规定，应对刘某履行赔偿义务的是（）。", "options": ["张某", "该派出所", "派出该派出所的公安局", "派出该派出所的公安局所属政府"], "a": 2, "e": ".【C】根据《公安机关办理国家赔偿案件程序规定》第二条：公安派出所、具有独立执法主体资格的公安机关内设机构及其工作人员侵犯公民、法人或者其他组织合法权益的，所属公安机关为赔偿义务机关。故正确答案是C。", "tag": "法律常识"},
{"id": "law-475", "q": "下列行为中，行政机关的做法构成滥用职权的是：", "options": ["工商部门对一批疑似走私的物品进行了查扣", "质量技术监督局作出处罚决定所适用的标准反复无常", "规划局为了公共利益的需要撤回了发给S 企业的规划许可证", "公安局对小钱处以拘留十日的处罚，未告知其事实、理由和依据"], "a": 1, "e": ".【B】滥用职权的行为主要表现为以下几种情况：一是超越职权，擅自决定或处理没有具体决定、处理权限的事项；二是玩弄职权，随心所欲地对事项作出决定或者处理；三是故意不履行应当履行的职责，或者说任意放弃职责；四是以权谋私、假公济私，不正确地履行职责。A项错误，工商部门有权力对疑似走私物品进行查扣。B项正确，“反复无常”属于“玩弄职权”，属于滥用职权的一种。C项错误，规划局作出撤回决定是由于“公共利益的需要”，这种情形下可以撤回许可证。D项错误，该项是“处罚程序”上出了问题，职权上并没有体现出“滥用”。故正确答案为B。本题有认为选D的，D属于行政处罚中未履行《行政处罚法》规定的“告知义务”，即不履行应当履行的职责。但是“滥用职权”必须是主观“故意”，而选项中未明确公安局的未告知是主观上的故意，还是过失，还是客观原因。所以D项是表述不严谨，而B项错误明显，所以粉笔题库倾向选B。", "tag": "法律常识"},
{"id": "law-476", "q": "甲、乙两镇分别位于某市的两个区。因一块林地的权属纠纷向市政府申请解决。市政府裁定林地属于甲镇，乙镇不服裁定，向省政府申请复议。复议机关确认争议的林地归属于乙镇。甲镇不服复议决定，于是提起行政诉讼。本案中，有管辖权的法院是（）。", "options": ["甲镇所在的区人民法院", "乙镇所在的区人民法院", "市中级人民法院", "省高级人民法院"], "a": 2, "e": ".【C】根据《行政诉讼法》第15条级别管辖的规定，“中级人民法院管辖下列第一审行政案件：（一）对国务院部门或者县级以上地方人民政府所作的行政行为提起诉讼的案件；”题目中，甲镇不服省政府作出的复议决定，被告为省政府的案件应该由中级人民法院管辖。《行政诉讼法》第18条第1款规定的是地域管辖，“行政案件由最初作出行政行为的行政机关所在地人民法院管辖。经复议的案件，也可以由复议机关所在地人民法院管辖。”也就是说该案可以由市政府所在地或省政府所在地的中级人民法院管辖，而非AB选项所说的区人民法院及D选项所说的省高级人民法院。故正确答案为C。", "tag": "法律常识"},
{"id": "law-477", "q": "下列不需要设定和实施行政许可的是（）。", "options": ["有限自然资源的开发利用需要赋予特定权利的事项", "提供公众服务并且直接关系公共利益的职业，需要确定具备特殊条件的事项", "行政机关采用事后监督等其他行政管理方式能够解决的事项", "企业或者其他组织的设立，需要确定主体资格的事项"], "a": 2, "e": ".【C】《中华人民共和国行政许可法》第十二条规定，下列事项可以设定行政许可：（一）直接涉及国家安全、公共安全、经济宏观调控、生态环境保护以及直接关系人身健康、生命财产安全等特定活动，需要按照法定条件予以批准的事项；（二）有限自然资源开发利用、公共资源配置以及直接关系公共利益的特定行业的市场准入等，需要赋予特定权利的事项；（三）提供公众服务并且直接关系公共利益的职业、行业，需要确定具备特殊信誉、特殊条件或者特殊技能等资格、资质的事项；（四）直接关系公共安全、人身健康、生命财产安全的重要设备、设施、产品、物品，需要按照技术标准、技术规范，通过检验、检测、检疫等方式进行审定的事项；（五）企业或者其他组织的设立等，需要确定主体资格的事项；（六）法律、行政法规规定可以设定行政许可的其他事项。”故A、B、D三项需要设定和实施行政许可。《中华人民共和国行政许可法》第十三条规定，本法第十二条所列事项，通过下列方式能够予以规范的，可以不设行政许可：（一）公民、法人或者其他组织能够自主决定的；（二）市场竞争机制能够有效调节的；（三）行业组织或者中介机构能够自律管理的；（四）行政机关采用事后监督等其他行政管理方式能够解决的。故C项不需要设定和实施行政许可。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-478", "q": "关于行政许可听证制度，下列说法不正确的是：", "options": ["行政许可听证程序既可以由行政机关主动启动，也可因许可事项的申请人、利害关系人的申请而启动\u0003", "行政许可涉及申请人与他人之间重大利益关系的，行政机关在做出行政许可决定前应当告知申请人、利害关系人享有", "行政许可的实施和结果应当公开", "申请人、利害关系人不承担行政机关组织听证的费用"], "a": 2, "e": ".【C】行政许可听证可以分为依职权的听证与依申请的听证两种。依职权的听证是行政机关依据法定职权主动启动的听证；依申请的听证是行政机关因许可事项的申请人、利害关系人的申请而启动的听证。我国《行政许可法》第四十七条规定：行政许可直接涉及申请人与他人之间重大利益关系的，行政机关在作出行政许可决定前，应当告知申请人、利害关系人享有要求听证的权利；申请人、利害关系人在被告知听证权利之日起5日内提出听证申请的，行政机关应当在20日内组织听证。申请人、利害关系人不承担行政机关组织听证的费用。根据我国《行政许可法》第五条的规定，行政许可的实施和结果应当公开，但是涉及国家秘密、商业秘密、个人隐私的除外。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-479", "q": "根据《中华人民共和国公务员法》规定，下列有关公务员制度的说法正确的是：", "options": ["公务员工资由其职务决定", "我国实行公务员职位分类制度", "公务员职务实行选任制和委任制", "挂职锻炼是公务员交流的方式之一"], "a": 1, "e": ".【B】A项错误，新《公务员法》第七十九条规定：“公务员实行国家统一规定的工资制度。公务员工资制度贯彻按劳分配的原则，体现工作职责、工作能力、工作实绩、资历等因素，保持不同领导职务、职级、级别之间的合理工资差距。国家建立公务员工资的正常增长机制。”因此，公务员工资不只是职务决定，还与多种因素相关。B项正确，新《公务员法》第十六条规定：“国家实行公务员职位分类制度。公务员职位类别按照公务员职位的性质、特点和管理需要，划分为综合管理类、专业技术类和行政执法类等类别。根据本法，对于具有职位特殊性，需要单独管理的，可以增设其他职位类别。各职位类别的适用范围由国家另行规定。”C项错误，新《公务员法》第四十条第一款规定：“公务员领导职务实行选任制、委任制和聘任制。公务员职级实行委任制和聘任制。”D项错误，新《公务员法》第六十九条规定：“国家实行公务员交流制度。公务员可以在公务员和参照本法管理的工作人员队伍内部交流，也可以与国有企业和不参照本法管理的事业单位中从事公务的人员交流。交流的方式包括调任、转任。”故正确答案为B。", "tag": "法律常识"},
{"id": "law-480", "q": "近年来，“民告官”案件时有发生，“民告官”的依据是：", "options": ["《中华人民共和国民法通则》", "《中华人民共和国刑事诉讼法》", "《中华人民共和国民事诉讼法》", "《中华人民共和国行政诉讼法》"], "a": 3, "e": ".【D】民告官，是行政诉讼或行政官司的俗称。行政诉讼是官民矛盾的化解机制。行政法调整的行政主体和行政相对人构成的行政关系以及在此基础上产生的监督行政关系，而这两部分内容分别体现的就是“官管民”和“民告官”的关系，例如行政复议和行政诉讼就是监督行政关系。故正确答案为D。", "tag": "法律常识"},
{"id": "law-481", "q": "根据我国《行政许可法》，下列说法不正确的是：", "options": ["国务院可以通过决定的形式设定行政许可", "省级政府规章可以设定行政许可", "省级发改委可以设定临时性的行政许可", "地方性法规可以设定行政许可"], "a": 2, "e": ".【C】《中华人民共和国行政许可法》第十四条规定：本法第十二条所列事项，法律可以设定行政许可。尚未制定法律的，行政法规可以设定行政许可。必要时，国务院可以采用发布决定的方式设定行政许可。实施后，除临时性行政许可事项外，国务院应当及时提请全国人民代表大会及其常务委员会制定法律，或者自行制定行政法规。第十六条规定：行政法规可以在法律设定的行政许可事项范围内，对实施该行政许可作出具体规定。地方性法规可以在法律、行政法规设定的行政许可事项范围内，对实施该行政许可作出具体规定。规章可以在上位法设定的行政许可事项范围内，对实施该行政许可作出具体规定。法规、规章对实施上位法设定的行政许可作出的具体规定，不得增设行政许可；对行政许可条件作出的具体规定，不得增设违反上位法的其他条件。省级发改委为省级政府职能部门无权创设行政许可。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-482", "q": "行政法在法律体系中的地位和作用，是由什么决定的？", "options": ["行政法律规范数量之多", "行政管理在国家生活中的地位", "行政法是基本部门法", "行政法关系到公民的权利和义务"], "a": 1, "e": ".【B】行政法在法律体系中的地位和作用是由行政管理在国家生活中的地位决定的。第一，从行政法的调整对象来看，行政法调整着广泛而重要的社会关系，这类社会关系与国家权力、公民权利息息相关，是公民权利与国家权力关系的重要组成部分；第二，从行政法与《宪法》的关系来看，行政法是《宪法》的重要的实施法；第三，从行政法与其他基本法律部门的关系来看，行政法对其他部门法的影响越来越大。故正确答案为B。", "tag": "法律常识"},
{"id": "law-483", "q": "根据《行政诉讼法》规定，下列有关行政诉讼的表述不正确的是：", "options": ["人民法院不受理对国防、外交等国家行为提起的行政诉讼", "被告对做出的具体行政行为负有举证责任", "人民法院审理行政案件，适用调解", "因不动产提起的行政诉讼，由不动产所在地人民法院管辖"], "a": 2, "e": ".【C】我国《行政诉讼法》第五十条规定：“人民法院审理行政案件，不适用调解。”行政诉讼不适用调解，这是由行政争议的特点所决定的。第一，行政争议是因行政机关行使国家行政管理权而发生的，行政权是国家的法定权力，它的行使是依据行政法进行的。第二，行政争议所反映的法律关系是一种纵向的管理与被管理的关系，不同于平等主体之间的民事关系，这种特殊的指挥、命令与服从关系，也使得双方当事人无法在产生争议后平等自愿地去协商并达成协议，而只有让第三者公断。第三，行政诉讼使人民法院对具体行政行为合法性进行审查，并不审查具体行政行为是否适当，在合法与违法之间不存在第三种选择。所谓不适用调解，主要是指人民法院不能以调解书的形式结束案件的审查。至于在受理之初，人民法院对当事人做些法律上的解释工作，晓之以理是可以的，双方当事人自愿达成协议也是允许的，但应以人民法院裁定的形式结案。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-484", "q": "行政行为以什么为标准，可分为羁束行为和自由裁量行政行为：", "options": ["受法律规范拘束的程度", "管理对象是否特定", "行政机关是否可以主动作出行政行为", "适用与效力作用的对象范围"], "a": 0, "e": ".【A】A项正确，行政行为依据不同的标准，可以分为不同的类别。以受法律规范约束的程度为标准，可分为羁束行政行为与自由裁量行政行为。B项错误，以管理对象是否特定为标准，行政行为分为抽象行政行为和具体行政行为。C项错误，以行政机关是否可以主动作出行政行为为标准，行政行为分为依职权行政行为与需申请的行政行为。D项错误，以适用与效力作用的对象范围为标准，可分为内部行政行为与外部行政行为。故正确答案为A。", "tag": "法律常识"},
{"id": "law-485", "q": "用人机关应当在市政府公务员主管部门同意聘任后多少日内，根据公开招聘或招聘计划与聘任制公务员按照平等自愿的原则，订立聘任合同，确定双方的权利和义务：", "options": ["30", "45", "60", "90"], "a": 2, "e": ".【C】深圳市人民政府办公厅2010年印发的《深圳市行政机关聘任制公务员管理办法（试行）》第二十条规定：“用人机关应当在市政府公务员主管部门同意聘任后60日内，根据公开招聘或选聘计划与聘任制公务员按照平等自愿的原则，订立聘任合同，确定双方的权利和义务。”故正确答案为C。", "tag": "法律常识"},
{"id": "law-486", "q": "《深圳市行政机关专业技术类公务员管理办法（试行）》所称专业技术类公务员，是指在深圳市行政机关中从事专业技术工作，履行专业技术职责，为机关实施公共管理提供专业技术支持和技术手段保障的公务员：", "options": ["聘任制", "选任制", "领导职务", "非领导职务"], "a": 3, "e": ".【D】《深圳市行政机关专业技术类公务员管理办法（试行）》第二条规定：“本法所称专业技术类公务员，是指在深圳市行政机关中从事专业技术工作，履行专业技术职责，为机关实施公共管理提供专业技术支持和技术手段保障的非领导职务公务员。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-487", "q": "乡、民族乡、镇的人民政府对村民委员会的工作：", "options": ["进行领导和决策", "进行监督检查", "进行管理和服务", "给予指导、支持和帮助"], "a": 3, "e": ".【D】《中华人民共和国村民委员会组织法》第四条规定：乡、民族乡、镇的人民政府对村民委员会的工作给予指导、支持和帮助，但是不得干预依法属于村民自治范围内的事项。故正确答案为D。", "tag": "法律常识"},
{"id": "law-488", "q": "下列行为中，违反《中华人民共和国选举法》的是：", "options": ["选民张某是文盲不能写选票，委托他的妻子代写", "某市A 区人大换届选举，当地B 公司未给本公司的15 名外来务工人员发放选民证", "某村22 岁的村民赵某经医院诊断为重症精神病患者，村里换届选举时，未给赵某发放选民证", "某村村委会换届选举，村民刘某发现公布的选民名单遗漏了邻居洪某的名字，遂向选举委员会提出申诉"], "a": 1, "e": ".【B】B选项错误，根据《选举法》第三条：“中华人民共和国年满十八周岁的公民，不分民族、种族、性别、职业、家庭出身、宗教信仰、教育程度、财产状况和居住期限，都有选举权和被选举权”，可知B项中B公司未发放选民证违反了选举法。本题为选非题，故正确答案为B。待选项辨析：A项：第三十六条：“选民如果是文盲或者因残疾不能写选票的，可以委托他信任的人代写”；C项：第二十六条：“精神病患者不能行使选举权利的，经选举委员会确认，不列入选民名单”；D项：第二十八条：“对于公布的选民名单有不同意见的，可以向选举委员会提出申诉”。由上面三条可知A、C、D均符合选举法规定。", "tag": "法律常识"},
{"id": "law-489", "q": "机关对全体公务员进行的更新知识、提高工作能力的培训是：", "options": ["业务培训", "在职培训", "任职培训", "技术培训"], "a": 1, "e": ".【B】新《公务员法》第六十七条第一款规定：“机关对新录用人员应当在试用期内进行初任培训；对晋升领导职务的公务员应当在任职前或者任职后一年内进行任职培训；对从事专项工作的公务员应当进行专门业务培训；对全体公务员应当进行提高政治素质和工作能力、更新知识的在职培训，其中对专业技术类公务员应当进行专业技术培训。”故正确答案为B。", "tag": "法律常识"},
{"id": "law-490", "q": "行政执法与行政权不可分离，这是由行政权的特点决定的。下列不属于行政执法特点的是：", "options": ["自由裁量", "不可放弃", "不告不理", "主体特定"], "a": 2, "e": ".【C】A、B、D三项正确，三者均为行政执法的特征。行政执法是指建立在近代国家权利的立法、执法、司法三分立的基础上的国家行政机关和法律委托的组织及其公职人员依照法定职权和程序行使行政管理权，贯彻实施国家立法机关所制定的法律的活动。行政执法具有以下特征：执法主体的法定性和国家代表性（即主体特定）、执法具有主动性和单方意志性（即不可放弃）、执法具有极大的自由裁量性（即自由裁量）；C项错误，不告不理是刑事诉讼和民事诉讼的原则，不是行政执法的特征。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-491", "q": "当行政行为违法时，下列选项中，除哪个单位外，都拥有撤销权：", "options": ["人民法院", "人民检察院", "国务院", "作出行政行为的机关"], "a": 1, "e": ".【B】A项错误，人民法院拥有撤销权。《行政诉讼法》第五十四条规定：“人民法院经过审理，根据不同情况，分别作出以下判决：……（二）具体行政行为有下列情形之一的，判决撤销或者部分撤销，并可以判决被告重新作出具体行政行为……”；B项正确，人民检察院不拥有任何撤销权；C项错误，国务院拥有撤销权。《宪法》第八十九条规定：“国务院行使下列职权：……（十三）改变或者撤销各部、各委员会发布的不适当的命令、指示和规章；（十四）改变或者撤销地方各级国家行政机关的不适当的决定和命令。……”；D项错误，作出行政行为的机关拥有撤销权。《行政诉讼法》第五十一条规定：“人民法院对行政案件宣告判决或裁定前，原告申请撤诉的，或者被告改变其所作的具体行政行为，原告同意并申请撤诉的，是否准许，由人民法院裁定。”该条规定说明，行政机关发现自己作出的行政行为有错可以依法自行撤销或改变行政行为。故正确答案为B。", "tag": "法律常识"},
{"id": "law-492", "q": "下列行为属于行政处罚的范围是：", "options": ["某食品药品监督局责令某食品厂召回其不符合食品安全标准的上市食品", "某工商局对一企业有效期届满未申请延续的营业执照予以注销", "某卫生局对流行性传染病患者强制隔离", "某公安交管局暂扣违章驾车张某的驾驶执照六个月"], "a": 3, "e": ".【D】A项错误，食品药监局的责令召回不符合食品安全标准的上市食品，是缺陷产品召回制度的规定，是一种特殊程序，是为了防止危害的发生而采取的措施，不是对食品生产者的惩罚，也不属于行政处罚；B项错误，行政许可的注销，仅是消灭行政许可法律关系的一种宣告，是一种法定程序，并不对行政相对人的权利义务产生影响，不具有惩罚性，不属于行政处罚；C项错误，卫生局对流行性传染病患者强制隔离，不是以制裁违法犯罪为直接目的，而是为了预防传染病的传播，依法对公民人身自由实施暂时性限制，属于行政强制措施而非行政处罚；D项正确，行政处罚，是国家行政机关对构成行政违法行为的公民、法人或者其他组织实施的行政法上的制裁。行政处罚是行政违法行为引起的法律后果，其目的在于对行政违法的行为人进行惩罚。根据《行政处罚法》第8条规定：“行政处罚的种类：（一）警告；（二）罚款；（三）没收违法所得、没收非法财物；（四）责令停产停业；（五）暂扣或者吊销许可证、暂扣或者吊销执照；（六）行政拘留；（七）法律、行政法规规定的其他行政处罚。”选项D中，张某违章驾车，被暂扣驾驶执照是违法行为造成的法律后果，是公安交管局对其的一种惩罚，属于行政处罚。故正确答案为D。", "tag": "法律常识"},
{"id": "law-493", "q": "行政法规是国务院为领导和管理国家各项行政工作，根据宪法和法律，并且按照《行政法规制定程序条例》的规定而制定的各类法规的总称。我国行政法规的名称中，“规定”是指：", "options": ["用于针对特定事件而采取的特定处置办法", "用于对某一方面的行政工作进行比较全面系统的规定", "用于对某一方面的行政工作进行部分的规定", "用于对某一项行政工作进行部分的规定"], "a": 2, "e": ".【C】《行政法规制定程序条例》中规定，对某一方面的行政工作做比较全面、系统的规定，称“条例”；对某一方面的行政工作做部分的规定，称“规定”；对某一项行政工作做比较具体的规定，称“办法”。故正确答案为C。", "tag": "法律常识"},
{"id": "law-494", "q": "行政诉讼的一审程序由起诉、受理、审理和裁判四个相互衔接的阶段构成，以下关于该四个阶段的相关表述中，不正确的一项是：", "options": ["原告起诉，应当有明确的被告和具体的诉讼请求", "人民法院对起诉作审查后，认为符合行政诉讼的受理条件的，应在7 日内立案受理", "行政诉讼一审审理的方式为书面审理", "经审理，人民法院认为行政处罚显失公正的，可以判决变更"], "a": 2, "e": ".【C】C项错误，行政诉讼第一审程序必须进行开庭审理，采取言词审理的方式。此种审理方式有利于当事人充分行使辩论权和其他诉讼权利，便于人民法院直接审理案件并在此基础上查明全部事实。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-495", "q": "具体行政行为是指行政主体在行政管理活动中行使行政权力，针对特定的相对人，就特定的具体事宜，做出的能对相对人实体权利、义务产生直接影响的行为。以下不属于具体行政行为的是：", "options": ["某县政府发布命令拆迁该县鼓楼街东西两侧30 米内的房屋", "某市住房和建设局与某建筑公司签订《住宅建设合同书》", "某税务局向某公司送达《减免税批准通知书》", "某工商局向公民甲颁发营业执照"], "a": 1, "e": ".【B】具体行政行为，是指行政主体在行政管理过程中，针对特定的人或事采取具体措施的行为。其行为的内容和结果将直接影响某一个人或组织的权利或义务，其最突出的特点就是行为对象的特定化和具体化，包括行政许可行为、行政处罚行为等。B项错误，属于民事合同，不属于具体行政行为。故正确答案为B。", "tag": "法律常识"},
{"id": "law-496", "q": "某区卫生行政部门根据《公共场所卫生管理条例》的相关规定，对某饭馆作出吊销卫生许可证的决定。这一行为属于行政（）。", "options": ["处罚", "监督", "强制执行", "强制措施"], "a": 0, "e": ".【A】本题考查法律常识。根据《行政处罚法》第8条规定：“行政处罚的种类……（五）暂扣或者吊销许可证、暂扣或者吊销执照……”因此，吊销卫生许可证属于行政处罚。故正确答案为A。", "tag": "法律常识"},
{"id": "law-497", "q": "在行政诉讼的执行措施中，可对行政机关采取的是：", "options": ["司法建议", "查封", "扣押", "划拨"], "a": 3, "e": ".【D】根据《行政诉讼法》第96条规定：“当事人必须履行人民法院发生法律效力的判决、裁定。行政机关拒绝履行判决、裁定的，第一审人民法院可以采取以下措施：（一）对应当归还的罚款或者应当给付的赔偿金，通知银行从该行政机关的账户内划拨（三）向该行政机关的上一级行政机关或者监察、人事机关提出司法建议。接受司法建议的机关，根据有关规定进行处理，并将处理情况告知人民法院”。因此，行政诉讼执行措施中，人民法院可对行政机关采取的是划拨。故正确答案为D。", "tag": "法律常识"},
{"id": "law-498", "q": "行政机关在其法定职权范围内，依照法律、法规、规章的规定，可以委托下列哪一机关或者单位实施行政许可：", "options": ["所属事业单位", "其他行政机关", "其他国家机关", "其他行政机关和所属事业单位"], "a": 1, "e": ".【B】《行政许可法》第二十四条规定：“行政机关在其法定职权范围内，依照法律、法规、规章的规定，可以委托其他行政机关实施行政许可。委托机关应当将受委托行政机关和受委托实施行政许可的内容予以公告。委托行政机关对受委托行政机关实施行政许可的行为应当负责监督，并对该行为的后果承担法律责任。受委托行政机关在委托范围内，以委托行政机关名义实施行政许可；不得再委托其他组织或者个人实施行政许可。”B项正确，行政许可只能委托行政机关进行。故正确答案为B。", "tag": "法律常识"},
{"id": "law-499", "q": "下列选项中错误的是：", "options": ["甲就其被处行政拘留处罚起诉后，由其所在地或被告所在地人民法院管辖。", "若利害关系人就行政许可要求组织听证，那么听证费用应由申请人承担。", "某派出所对乙作出行政拘留的处罚决定，乙遂向其县级人民政府申请行政复议。", "丙工厂将排污口建在行洪道上并违规排放，某市环保局与市水利局对该工厂分别作出处罚。"], "a": 1, "e": ".【B】B项错误，《行政许可法》第四十七条规定：“行政许可直接涉及申请人与他人之间重大利益关系的，行政机关在作出行政许可决定前，应当告知申请人、利害关系人享有要求听证的权利；申请人、利害关系人在被告知听证权利之日起五日内提出听证申请的，行政机关应当在二十日内组织听证。申请人、利害关系人不承担行政机关组织听证的费用。”本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-500", "q": "下列选项中不准确的是：", "options": ["行政处罚通常由违法行为发生地的县级以上有权行政主体管辖", "在我国，人民检察院对行政案件的审理进行监督主要是采用抗诉的方式", "行政机关作出影响相对方权利义务决定后，应说明作出决定的法律依据", "行政机关发现对公民、法人或其他组织作出的行政处罚有错误的，应当主动改正"], "a": 2, "e": ".【C】C项错误，行政机关应该在作出影响相对方权利义务决定之前，说明法律依据，并非之后。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-501", "q": "下列属于不可以提起复议的行为是：", "options": ["国务院某部门的《关于提高食盐出厂（场）价格的通知》", "某市政府的《XX 市农村社会基本养老保险实施细则》", "某镇政府的《关于出生人口性别比升高专项整治活动的意见》", "某省人大的《××省实施＜中华人民共和国消费者权益保护法＞办法》"], "a": 3, "e": ".【D】本题考查与行政复议相关的行政法知识。《行政复议法》第七条规定，公民、法人或者其他组织认为行政机关的具体行政行为所依据的下列规定不合法，在对具体行政行为申请行政复议时，可以一并向行政复议机关提出对该规定的审查申请：（一）国务院部门的规定；（二）县级以上地方各级人民政府及其工作部门的规定；（三）乡、镇人民政府的规定。前款所列规定不含国务院部、委员会规章和地方人民政府规章。规章的审查依照法律、行政法规办理。A项正确，国务院某部门的《关于提高食盐出厂（场）价格的通知》属于国务院部门的规定。B项正确，某市政府的《XX市农村社会基本养老保险实施细则》属于县级以上地方各级人民政府及其工作部门的规定。C项正确，某镇政府的《关于出生人口性别比升高专项整治活动的意见》属于）乡、镇人民政府的规定D项错误，某省人大的《XX省实施〈中华人民共和国消费者权益保护法〉办法》属于地方性法规。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-502", "q": "下列行为中不属于行政行为的是：", "options": ["某国家机关为建住宅楼与某建筑公司签订建筑工程承包合同", "某县技术监督局对所辖境内某化工厂生产国家明令淘汰的产品的行为予以处罚", "国家知识产权局专利复审委员会根据利害关系人申请，宣告某专利权无效", "工商行政管理机关为符合条件的企业颁发营业执照"], "a": 0, "e": ".【A】本题要求选出“不属于”行政行为的一项。行政行为是指行政主体行使行政职权，作出的能够产生行政法律效果的行为。某国家机关为建住宅楼与某建筑公司签订建筑工程承包合同属于平等的民事主体发生的民事法律关系，不属于行政行为的范畴。故正确答案为A。", "tag": "法律常识"},
{"id": "law-503", "q": "某市安全生产监督管理局在进行全市煤矿企业安全情况大检查时，发现甲企业在安全生产方面存在巨大隐患，责令该企业停产停业进行整顿，该企业对此决定不服，该企业：", "options": ["可以向该市安全生产监督管理局申请行政复议", "只能向该市市政府申请行政复议", "可以直接向人民法院提起行政诉讼", "应该先向该市市政府申请行政复议，若不服复议决定，再向人民法院提起行政诉讼"], "a": 2, "e": ".【C】AB项错误，根据《行政复议法》第十二条规定：“对县级以上地方各级人民政府工作部门的具体行政行为不服的，由申请人选择，可以向该部门的本级人民政府申请行政复议，也可以向上一级主管部门申请行政复议。”因此，该企业可以向该市市政府或该市上一级市场监督管理局主管部门—省安全生产监督管理局申请行政复议。C项正确，根据《行政诉讼法》第四十四条规定：“对属于人民法院受案范围的行政案件，公民、法人或者其他组织可以先向行政机关申请复议，对复议决定不服的，再向人民法院提起诉讼；也可以直接向人民法院提起诉讼。”因此，该公司直接向人民法院提起行政诉讼的行为是正确的。D项错误，根据C项引用法条内容，该企业“可以”而不是“应该”先向市政府申请行政复议。“应该”一词更具指向性，而“可以”更具选择性。故正确答案为C。", "tag": "法律常识"},
{"id": "law-504", "q": "下列关于设立行政许可与行政处罚的说法中，正确的是：", "options": ["行政许可与行政处罚的设定机关均应定期对其设定的行政许可、行政处罚进行评价", "部门规章可以依法设定一定的行政许可、行政处罚", "尚未制定法律的，行政法规可以依法设定一定的行政许可、行政处罚", "法律、法规、规章以外的其他规范性文件一律不得设定任何行政许可、行政处罚"], "a": 2, "e": ".【C】本题考查法律常识，主要涉及行政许可法与行政处罚法的相关知识。A项错误，《行政许可法》第二十条规定，行政许可的设定机关应当定期对其设定的行政许可进行评价，但行政处罚法没有相关规定；B项错误，根据《行政许可法》第十六条和《行政处罚法》第十二条，部门规章只能对已经设定的行政许可作出实施的具体规定，但可以在法律、法规没有规定的情况下设定一定的行政处罚；C项正确，根据《行政许可法》第十四条，尚未制定法律的，行政法规可以设定行政许可，根据《行政处罚法》第十一条，地方性法规可以设定除限制人身自由、吊销企业营业执照以外的行政处罚；D项错误，根据《行政许可法》第十四条，必要时，国务院可以采用发布决定的方式设定行政许可。故正确答案为C。", "tag": "法律常识"},
{"id": "law-505", "q": "国家对超标准排放污水的单位收取排污费，属于：", "options": ["行政征购", "行政处罚", "行政征用", "行政征收"], "a": 3, "e": ".【D】行政征收是指行政机关或者法定授权的组织根据法律、法规的规定，向公民、法人或者其他组织无偿收取一定财物的行政行为。行政征收须以公民、法人或者其他组织负有行政法上的缴纳义务为前提，其实质是国家以强制方式无偿取得管理相对人一定财产所有权。行政征收的主要内容有税收征收、资源费征收、建设资金征收、排污费征收及其他法定征收。故正确答案为D。", "tag": "法律常识"},
{"id": "law-506", "q": "高某无证经营被区工商局罚款300 元，高某不服申请复议，复议机关市工商局决定罚款600 元，后经确认，区工商局所作的罚款行政处罚违反法律，下列说法正确的是：", "options": ["高某可以请求区工商局赔偿600 元", "高某可以请求市工商局赔偿600 元", "高某既可以请求区工商局赔偿600 元，又可以请求市工商局赔偿600 元", "高某可以请求区工商局赔偿300 元，市工商局赔偿300 元"], "a": 3, "e": ".【D】本题考查法律常识，主要涉及《国家赔偿法》的相关知识。《国家赔偿法》第八条规定：“经复议机关复议的，最初造成侵权行为的行政机关为赔偿义务机关，但复议机关的复议决定加重损害的，复议机关对加重的部分履行赔偿义务。”本题中区工商局作出罚款300元的决定，复议机关市工商局决定罚款600元，复议机关应对加重的300元罚款承担责任，因此区工商局所做的罚款行政处罚违反法律时，复议机关的决定也是不当的，因此高某可以请求区工商局赔偿300元，市工商局就加重的部分承担赔偿责任。故正确答案为D。", "tag": "法律常识"},
{"id": "law-507", "q": "甲因不服工商行政管理机关行政处罚决定向上级机关申请复议，要求撤销处罚决定，但没有提出赔偿请求。复议机关经审查认为该处罚决定违法，决定予以撤销。对于处罚决定造成的财产损失，复议机关正确的做法是什么：", "options": ["解除查封的同时决定被申请人赔偿相应的损失", "解除查封并告知申请人就赔偿问题另行申请复议", "解除查封的同时就损失问题进行调解", "解除查封的同时要求申请人增加关于赔偿的复议申请"], "a": 0, "e": ".【A】本题考查法律常识，主要涉及行政法的相关知识。《行政复议法》第二十九条第二款规定：“申请人在申请行政复议时没有提出行政赔偿请求的，行政复议机关在依法决定撤销或者变更罚款，撤销违法集资、没收财物、征收财物、摊派费用以及对财产的查封、扣押、冻结等具体行政行为时，应当同时责令被申请人返还财产，解除对财产的查封、扣押、冻结措施，或者赔偿相应的价款。”根据本条规定，复议机关正确的做法是解除查封的同时决定被申请人赔偿相应的损失。A项符合题意。故正确答案为A。", "tag": "法律常识"},
{"id": "law-508", "q": "我国法律规定行政处罚和刑罚可以折抵，但下列哪种情况不能出现：", "options": ["罚款可以折抵罚金", "行政拘留可以折抵拘役", "行政拘留可以折抵有期徒刑", "没收违法所得可以折抵没收财产"], "a": 3, "e": ".【D】A、B、C项正确，我国《行政处罚法》第二十八条规定：“违法行为构成犯罪，人民法院判处拘役或者有期徒刑时，行政机关已经给予当事人行政拘留的，应当依法折抵相应刑期。违法行为构成犯罪，人民法院判处罚金时，行政机关已经给予当事人罚款的，应当折抵相应罚金”。D项错误，“没收违法所得”是《行政处罚法》第八条中规定的行政处罚种类，它是指行政机关将行政违法行为人占有的，通过违法途径和方法取得的财物收归国有的制裁方法。而“没收财产”则是《刑法》第五十九条中规定的刑罚附加刑之一，它是指将犯罪人所有财产的一部分或者全部强制无偿地收归国有的刑罚种类。“没收违法所得”没收的是通过违法途径和方法取得的财物，而“没收财产”没收的是犯罪人所有财产的一部分或者全部，“没收财产”作为一种附加刑，实际上是没收犯罪人合法所有并且没有用于犯罪的财产；不得以追缴犯罪所得，没收违禁品与供犯罪所用的本人财物来代替或折抵没收财产。因此，没收违法所得不能折抵没收财产。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-509", "q": "具体行政行为的效力不包括：", "options": ["执行力", "拘束力", "确定力", "公信力"], "a": 3, "e": ".【D】具体行政行为的效力包括确定力、拘束力和执行力。确定力：具体行政行为一旦作出，不得随意更改；已确定的行政决定，公民无权自行变更；已确定的行政执法行为，非经法定程序行政机关不得随意改变。拘束力：具体行政行为生效后，必须按照已经确定的内容实施行为，相对人必须遵守和实际履行行政行为规定的义务。执行力：国家强制当事人实施具体行政行为所要求的义务。具体行政行为的效力不包括公信力。本题为选非题，故正确答案为D。本题相关知识点：具体行政行为，即指行政机关行使行政权力，对特定的公民、法人和其他组织作出的有关其权利义务的单方行为。具体行政行为特征：", "tag": "法律常识"},
{"id": "law-510", "q": "卫生部和国家工商行政管理总局对某国有企业共同作出一项处罚，该企业不服，欲申请行政复议，下列表述正确的是（）。", "options": ["该企业应当向国务院申请行政复议，由国务院作出行政复议决定", "该企业可以同时向两个机构申请行政复议，由国务院作出行政复议决定", "该企业可以同时向这两个机构申请行政复议，由作出具体行政行为的国务院机构共同作出行政复议决定", "该企业可以向其中任何一个机构申请行政复议，由作出具体行政行为的国务院机构共同作出行政复议决定"], "a": 3, "e": ".【D】《行政复议法》第四章，行政复议受理第十四条规定，对国务院部门或者省、自治区、直辖市人民政府的具体行政行为不服的，向作出该具体行政行为的国务院部门或者省、自治区、直辖市人民政府申请行政复议。对行政复议决定不服的，可以向人民法院提起行政诉讼；也可以向国务院申请裁决，国务院依照本法的规定作出最终裁决。本题考查的是行政执法对象对国务院部门或者省、自治区、直辖市人民政府的具体行政处罚不服申请行政复议的受理范围。由于卫生部和国家工商行政管理总局对此国有企业共同作出了处罚，所以该企业可以同时向任何一个机构申请行政复议，由作出具体行政行为的国务院机构同时作出行政复议决定。故正确答案为D。", "tag": "法律常识"},
{"id": "law-511", "q": "下列关于行政诉讼的被告的表述中，不正确的是：", "options": ["它只能是组织，而不能是个人", "它是被诉的一方当事人，可以以自己的名义应诉", "对共同行政行为不服的，作出共同行政行为的行政机关为共同被告", "在行政委托关系中，被委托的行政机关是被告"], "a": 3, "e": ".【D】《中华人民共和国行政诉讼法》第二十六条规定，“行政机关委托的组织所作的行政行为，委托的行政机关是被告。”本题为选非题，故正确答案为D。本题相关知识点：关于行政诉讼的被告，《行政诉讼法》第二十六条规定的完整内容如下：“公民、法人或者其他组织直接向人民法院提起诉讼的，作出行政行为的行政机关是被告。经复议的案件，复议机关决定维持原行政行为的，作出原行政行为的行政机关和复议机关是共同被告；复议机关改变原行政行为的，复议机关是被告。复议机关在法定期限内未作出复议决定，公民、法人或者其他组织起诉原行政行为的，作出原行政行为的行政机关是被告；起诉复议机关不作为的，复议机关是被告。两个以上行政机关作出同一行政行为的，共同作出行政行为的行政机关是共同被告。行政机关委托的组织所作的行政行为，委托的行政机关是被告。行政机关被撤销或者职权变更的，继续行使其职权的行政机关是被告。”", "tag": "法律常识"},
{"id": "law-512", "q": "关于“一事不再罚原则”的表述正确的是：", "options": ["针对同一违法行为，不能进行多种处罚", "针对同一违法行为，不能由两个或两个以上的行政机关进行处罚", "不能进行两次或两次以上的罚款", "不能依据同一法律规范进行两次或两次以上的处罚"], "a": 2, "e": ".【C】“一事不再罚”是行政处罚的基本原则之一，《中华人民共和国行政处罚法》第二十四条规定：对当事人的同一个违法行为，不得给予两次以上罚款的行政处罚。其基本含义是对当事人的同一个违法行为，不得以同一事实和同一理由给予两次以上罚款的行政处罚。同一事实是指同一个违法行为，即从其构成要件上，只符合一个违法行为的特征。同一理由是指同一法律依据。另外，当同一个违法行为触及多个法律规范需要处罚时，应按照以下原则：（1）法律法规有特殊规定的，从其规定；（2）无特殊规定的，按法律位阶确定处罚适用法律规范，高位阶优于低位阶；（3）如果同一位阶法律，则应从一重处（即重的行为吸收轻的行为）；（4）如果以上原则均难以处理或不适应，应按目的行为吸收手段行为、结果行为吸收方法行为并兼顾法律效用选择适用法律规范。故正确答案为C。", "tag": "法律常识"},
{"id": "law-513", "q": "甲地税务机关在调查中发现，某影视明星乙在五年前采取拆分合同的方式偷逃个人所得税达百万元，下列说法中错误的是（）。", "options": ["乙少缴的税款尚在追征期内，因此税务机关有权对乙追征税款", "从滞纳税款之日起，税务机关可对乙按日加收万分之五的滞纳金", "除追缴税款和滞纳金外，税务机关可对乙并处少缴税款三倍罚款", "若乙在规定期限内缴纳所有款项，已受行政处罚，可不予追究刑事责任"], "a": 0, "e": ".【A】本题考查法律常识。A项错误，根据《税收征管法》第五十二条规定：“因税务机关的责任，致使纳税人、扣缴义务人未缴或者少缴税款的，税务机关在三年内可以要求纳税人、扣缴义务人补缴税款，但是不得加收滞纳金。因纳税人、扣缴义务人计算错误等失误，未缴或者少缴税款的，税务机关在三年内可以追征税款、滞纳金；有特殊情况的，追征期可以延长到五年。对偷税、抗税、骗税的，税务机关追征其未缴或者少缴的税款、滞纳金或者所骗取的税款，不受前款规定期限的限制。”乙采取拆分合同的方式偷税，税务机关追征税款、滞纳金，没有追征期限的限制。B项正确，根据《税收征管法》第三十二条规定：“纳税人未按照规定期限缴纳税款的，扣缴义务人未按照规定期限解缴税款的，税务机关除责令限期缴纳外，从滞纳税款之日起，按日加收滞纳税款万分之五的滞纳金。”C项正确，根据《税收征管法》第六十三条第一款规定：“纳税人伪造、变造、隐匿、擅自销毁帐簿、记帐凭证，或者在帐簿上多列支出或者不列、少列收入，或者经税务机关通知申报而拒不申报或者进行虚假的纳税申报，不缴或者少缴应纳税款的，是偷税。对纳税人偷税的，由税务机关追缴其不缴或者少缴的税款、滞纳金，并处不缴或者少缴的税款百分之五十以上五倍以下的罚款；构成犯罪的，依法追究刑事责任。”乙少缴应纳税款，属于偷税，税务机关有权对其并处少缴的税款百分之五十以上五倍以下的罚款。D项正确，根据《刑法》第二百零一条规定：“纳税人采取欺骗、隐瞒手段进行虚假纳税申报或者不申报，逃避缴纳税款数额较大并且占应纳税额百分之十以上的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大并且占应纳税额百分之三十以上的，处三年以上七年以下有期徒刑，并处罚金。扣缴义务人采取前款所列手段，不缴或者少缴已扣、已收税款，数额较大的，依照前款的规定处罚。对多次实施前两款行为，未经处理的，按照累计数额计算。有第一款行为，经税务机关依法下达追缴通知后，补缴应纳税款，缴纳滞纳金，已受行政处罚的，不予追究刑事责任；但是，五年内因逃避缴纳税款受过刑事处罚或者被税务机关给予二次以上行政处罚的除外。”税务机关下达追缴通知后，如果乙在规定期限补缴税款，缴纳滞纳金的，已受行政处罚的，不予追究刑事责任。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-514", "q": "2018 年3 月23 日，A 市B 区公安局对甲作出行政拘留15 日的处罚，甲不服，于4 月5 日向市公安局提起行政复议。4月19 日，市公安局经审查认为处罚过重，遂改为拘留5 日，甲于4 月20 日收到复议决定书，但依旧不服，遂提起行政诉讼。基于本案，下列说法错误的是（）。", "options": ["本案中，区公安局和市公安局为共同被告", "甲对区公安局不服，申请复议时，也可以选择区政府作为复议机关", "若本案涉及个人隐私，则法院应当不公开审理", "甲应当在收到复议决定书之日起15 日内向法院提起行政诉讼"], "a": 0, "e": ".【A】本题考查法律常识。A项错误，《行政诉讼法》第二十六条第二款规定：“经复议的案件，复议机关决定维持原行政行为的，作出原行政行为的行政机关和复议机关是共同被告；复议机关改变原行政行为的，复议机关是被告。”在本案中，市公安局改变了原行政行为，因此，本案的被告应当是市公安局。B项正确，《行政复议法》第十二条第一款规定：“对县级以上地方各级人民政府工作部门的具体行政行为不服的，由申请人选择，可以向该部门的本级人民政府申请行政复议，也可以向上一级主管部门申请行政复议。”因此，甲可以向市公安局或者区政府申请行政复议。故表述正确。C项正确，《行政诉讼法》第五十四条规定：“人民法院公开审理行政案件，但涉及国家秘密、个人隐私和法律另有规定的除外。涉及商业秘密的案件，当事人申请不公开审理的，可以不公开审理。”故表述正确。D项正确，《行政诉讼法》第四十五条规定：“公民、法人或者其他组织不服复议决定的，可以在收到复议决定书之日起十五日内向人民法院提起诉讼。复议机关逾期不作决定的，申请人可以在复议期满之日起十五日内向人民法院提起诉讼。法律另有规定的除外。”故表述正确。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-515", "q": "下列对行政行为类型的判断正确的是（）", "options": ["某县交警大队因吕某酒驾暂扣其驾驶证——行政强制执行", "某县公安局对张某加处罚款——行政强制措施", "某区工商局为李某颁发营业执照——行政许可", "某地海关因陈某涉嫌走私扣押其货物——行政处罚"], "a": 2, "e": ".【C】本题考查法律常识。A项错误，《中华人民共和国行政处罚法》第八条规定：“行政处罚的种类：（一）警告；（二）罚款；（三）没收违法所得、没收非法财物；（四）责令停产停业；（五）暂扣或者吊销许可证、暂扣或者吊销执照；（六）行政拘留；（七）法律、行政法规规定的其他行政处罚。”因此，交警大队暂扣吕某的驾驶证的行为属于行政处罚。B项错误，行政强制执行，是指行政机关或者行政机关申请人民法院，对不履行行政决定的公民、法人或者其他组织，依法强制履行义务的行为。《中华人民共和国行政强制法》第十二条规定：“行政强制执行的方式：（一）加处罚款或者滞纳金；（二）划拨存款、汇款；（三）拍卖或者依法处理查封、扣押的场所、设施或者财物；（四）排除妨碍、恢复原状；（五）代履行；（六）其他强制执行方式。”因此，公安局加处罚款的行为属于行政强制执行。C项正确，行政许可，是指行政机关根据公民、法人或者其他组织的申请，经依法审查，准予其从事特定活动的行为。主要的表现形式是许可证和执照。D项错误，行政强制措施，是指行政机关在行政管理过程中，为制止违法行为、防止证据损毁、避免危害发生、控制危险扩大等情形，依法对公民的人身自由实施暂时性限制，或者对公民、法人或者其他组织的财物实施暂时性控制的行为。《中华人民共和国行政强制法》第九条规定：“行政强制措施的种类：（一）限制公民人身自由；（二）查封场所、设施或者财物；（三）扣押财物；（四）冻结存款、汇款；（五）其他行政强制措施。”因此，海关扣押货物的行为属于行政强制措施。故正确答案为C。", "tag": "法律常识"}
);
